      "originalScript": "ನಾನು ಇಲ್ಲಿ ವಿಷ್ಣುವಿನ ನಾರಾಯಣನ ಪೂಜೆಯನ್ನು ಮಾಡ್ತಾ ಇದ್ದೇನೆ ಆದ್ದರಿಂದಾಗಿ ಈ ಪ್ರತಿಮೆಯನ್ನು, ಒಂದು ಲಕ್ಷ್ಮೀ ನಾರಾಯಣ ಪ್ರತಿಮೆ, ಇನ್ನೊಂದು ಅಂಬೆಗಾಲು ಕೃಷ್ಣ, ಮತ್ತೆ ಸಾಲಿಗ್ರಾಮವನ್ನು ಪೂಜೆಗೆ ನಾನು ಇಟ್ಕೊಂಡಿದ್ದೇನೆ. ಜೊತೆಗೆ ದೇವರ ಅಭಿಷೇಕಕ್ಕೆ ಶಂಖ, ಶಂಖವನ್ನು ನಾನು ಉಪಯೋಗಿಸ್ತಾ ಇದ್ದೇನೆ. ಮತ್ತೆ ನಾರಾಯಣನಿಗೆ ನಾರಾಯಣನ ಇನ್ನೊಂದು ರೂಪ, ರಾಮನಿಗೆ ಅತ್ಯಂತ ಪ್ರಿಯವಾದ ಮುಖ್ಯ ಪ್ರಾಣ ಹನುಮಂತನ ಪ್ರತಿಮೆಯನ್ನು ನಾನು ಇಟ್ಕೊಂಡಿದ್ದೇನೆ. ಪೂಜೆಗೆ ಗಂಟೆ ಬೇಕೇ ಬೇಕು. ಗಂಟಾನಾದ ಯಾವಾಗಲೂ ಇರಬೇಕು ಆದ್ದರಿಂದಾಗಿ ಗಂಟೆಯನ್ನು ಕೂಡ ನಾನು ಇಟ್ಕೊಂಡಿದ್ದೇನೆ. ಆಮೇಲೆ ಕೆಲವರು ನಾರಾಯಣನ ಪರಿವಾರವಾಗಿ ಗರುಡನ ಪ್ರತಿಮೆಯನ್ನು, ಶೇಷವನ ಪ್ರತಿಮೆಯನ್ನು ಕೂಡ ಅವರು ಬಳಸ್ತಾರೆ. ಅದನ್ನು ಕೂಡ ಇಟ್ಕೊಳ್ಬಹುದು. ಹಾಗಾಗಿ ವಿಷ್ಣು ಪೂಜೆಗಂತೂ ಇಷ್ಟು ಪರಿಕರಗಳು ಬೇಕೇ ಬೇಕು. ",
      "captionOriginal": "ವಿಷ್ಣುವಿನ ನಾರಾಯಣನ ಪೂಜೆಯನ್ನ ಮಾಡ್ತಾ ಇದ್ದೇನೆ ಆದ್ದರಿಂದಾಗಿ ಈ ಪ್ರತಿಮೆಯನ್ನ ಒಂದು ಲಕ್ಷ್ಮಿ ನಾರಾಯಣ ಪ್ರತಿಮೆ ಇನ್ನೊಂದು ಅಂಬಿಕಾಲು ಕೃಷ್ಣ ಮತ್ತೆ ಸಾಲಿಗ್ರಾಮವನ್ನ ಪೂಜೆಗೆ ಇಟ್ಟುಕೊಂಡಿದ್ದೇನೆ ಜೊತೆಗೆ ದೇವರ ಅಭಿಷೇಕಕ್ಕೆ ಶಂಖ ಶಂಖವನ್ನು ನಾನು ಉಪಯೋಗಿಸುತ್ತಿದ್ದೇನೆ ಮತ್ತೆ ನಾರಾಯಣನಿಗೆ ನಾರಾಯಣನ ಇನ್ನೊಂದು ರೂಪ ರಾಮನಿಗೆ ಅತ್ಯಂತ ಪ್ರಿಯವಾದ ಮುಖ್ಯ ಪ್ರಾಣ ಹನುಮಂತನ ಪ್ರತಿಮೆಯನ್ನು ನಾನು ಇಟ್ಕೊಂಡಿದ್ದೇನೆ ಪೂಜೆಗೆ ಗಂಟೆ ಬೇಕು ಬೇಕು ಗಂಟಾನಾದ ಯಾವಾಗಲೂ ಇರಬೇಕು ಆದ್ದರಿಂದಾಗಿ ಗಂಟೆಯನ್ನು ಕೂಡ ನಾನು ಇಟ್ಕೊಂಡಿದ್ದೇನೆ ಆಮೇಲೆ ಕೆಲವರು ನಾರಾಯಣನ ಪರಿವಾರವಾಗಿ ಗರುಡನ ಪ್ರತಿಮೆಯನ್ನು ಶೇಷವನ ಪ್ರತಿಮೆಯನ್ನು ಕೂಡ ಅವರು ಬಳಸುತ್ತಾರೆ ಅದನ್ನು ಕೂಡ ಇಟ್ಟುಕೊಳ್ಳಬಹುದು ಹಾಗಾಗಿ ವಿಷ್ಣು ಪೂಜೆಗಂತೂ ಇಷ್ಟು ಪರಿಕರಗಳು ಬೇಕೇ ಬೇಕು ಮೊದಲಿಗೆ ಸ್ನಾನ ಮಾಡಿ ಬಂದ ನಂತರ ದೇವರ ನೀರನ್ನ",
      "losslessRoman": "nānu illi viṣṇuvina nārāyaṇana pūjeyannu māḍtā iddēne āddariṁdāgi ī pratimeyannu, oṁdu lakṣmī nārāyaṇa pratime, innoṁdu aṁbegālu kr̥ṣṇa, matte sāligrāmavannu pūjege nānu iṭkoṁḍiddēne. jotege dēvara abhiṣēkakke śaṁkha, śaṁkhavannu nānu upayōgistā iddēne. matte nārāyaṇanige nārāyaṇana innoṁdu rūpa, rāmanige atyaṁta priyavāda mukhya prāṇa hanumaṁtana pratimeyannu nānu iṭkoṁḍiddēne. pūjege gaṁṭe bēkē bēku. gaṁṭānāda yāvāgalū irabēku āddariṁdāgi gaṁṭeyannu kūḍa nānu iṭkoṁḍiddēne. āmēle kelavaru nārāyaṇana parivāravāgi garuḍana pratimeyannu, śēṣavana pratimeyannu kūḍa avaru baḷastāre. adannu kūḍa iṭkoḷbahudu. hāgāgi viṣṇu pūjegaṁtū iṣṭu parikaragaḷu bēkē bēku.",
