      "title": "Removing the nirmālya",
      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "modalige nirmālya visarjaneyannu māḍabēku. aṁtaṁdare hiṁdina dina nāvu ēnu dēvarige hūvu tuḷasigaḷanna nāvu arpaṇe māḍirtēve, adannu oṁdu dēvara balabhāgadalli oṁdu taṭṭeyanna iṭṭu ā taṭṭeyalli adannella saṁgraha māḍabēku. saṁgraha māḍi adannu tuḷiyadē iruva jāgakke, giḍada keḷagaḍe hākuvudu. matte īga nirmālya abhiṣēka.",
      "devanagari": "ವಿಸರ್ಜನೆಯನ್ನ ಮಾಡಬೇಕು ಅಂತ ಅಂದ್ರೆ ಹಿಂದಿನ ದಿನ ನಾವೇನು ದೇವರಿಗೆ ಆ ಹೂವು ತುಳಸಿಗಳನ್ನ ನಾವು ಅರ್ಪಣೆ ಮಾಡಿರುತ್ತೇವೆ ಅದನ್ನ ಒಂದು ದೇವರ ಬಲಭಾಗದಲ್ಲಿ ಒಂದು ತಟ್ಟೆಯನ್ನಿಟ್ಟು ಆ ತಟ್ಟೆಯಲ್ಲಿ ಅದನ್ನೆಲ್ಲ ಸಂಗ್ರಹ ಮಾಡೋದು ಸಂಗ್ರಹ ಮಾಡಿ ಅದನ್ನ ತುಳಿಯದೆ ಇರುವ ಜಾಗಕ್ಕೆ ಗಿಡದ ಕೆಳಗಡೆ ಮತ್ತೆ ಈಗ ನಿರ್ಮಾಲ್ಯ ಅಭಿಷೇಕ",
      "meaning": "Complete source-audio coverage for removing the nirmālya.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ಮೊದಲಿಗೆ ನಿರ್ಮಾಲ್ಯ ವಿಸರ್ಜನೆಯನ್ನು ಮಾಡಬೇಕು. ಅಂತಂದರೆ ಹಿಂದಿನ ದಿನ ನಾವು ಏನು ದೇವರಿಗೆ ಹೂವು ತುಳಸಿಗಳನ್ನ ನಾವು ಅರ್ಪಣೆ ಮಾಡಿರ್ತೇವೆ, ಅದನ್ನು ಒಂದು ದೇವರ ಬಲಭಾಗದಲ್ಲಿ ಒಂದು ತಟ್ಟೆಯನ್ನ ಇಟ್ಟು ಆ ತಟ್ಟೆಯಲ್ಲಿ ಅದನ್ನೆಲ್ಲ ಸಂಗ್ರಹ ಮಾಡಬೇಕು. ಸಂಗ್ರಹ ಮಾಡಿ ಅದನ್ನು ತುಳಿಯದೇ ಇರುವ ಜಾಗಕ್ಕೆ, ಗಿಡದ ಕೆಳಗಡೆ ಹಾಕುವುದು. ಮತ್ತೆ ಈಗ ನಿರ್ಮಾಲ್ಯ ಅಭಿಷೇಕ. ",
