      "title": "Nirmālya abhiṣēka with Śrī verses",
      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "śrī sūktadiṁda abhiṣēkavannu māḍuvudu. śrī sūktavū kūḍa obbobbaru oṁdē rītiyāgi uccāra māḍtāre āddariṁdāgi, nānu illi ślōkadaṁte mātra śrī sūktavannu hēḷtā iddēne. mahādēvyai ca vidhmahē viṣṇupatnyai ca dhīmahi, tannō lakṣmīḥ pracōdayāt. sarasijanilayē sarōjahastē dhavaḷatarāṁśukagaṁdhamālyaśōbhē, bhagavati harivallabhē manōjñē tribhuvanabhūtikari prasīda mahyaṁ. yāsā padmāsanasthā vipulakaṭitaṭī padmapatrāyatākṣī, gaṁbhīrāvartanābhistanabharanamitā śubhravastrōttarīyā. lakṣmīrdivyairgajēṁdrairmaṇigaṇakhacitaiḥ snāpitā hēmakuṁbhaiḥ, nityaṁ sā padmahastā mama vasatu gr̥hē sarvamāṁgalyayuktā. sarvamaṁgaḷa māṁgalyē śivē sarvārthasādhikē, śaraṇyē tryaṁbakē dēvi nārāyaṇi namōstutē eṁdu śrī sūktadiṁda dēvarige abhiṣēka māḍida naṁtara.",
      "devanagari": "ಸೂಕ್ತದಿಂದ ಅಭಿಷೇಕವನ್ನು ಮಾಡುವುದು ಶ್ರೀ ಸೂಕ್ತವು ಕೂಡ ಒಬ್ಬೊಬ್ಬರು ಅದೇ ರೀತಿಯಾಗಿ ಉಚ್ಚಾರ ಮಾಡುತ್ತಾರೆ ಆದ್ದರಿಂದಾಗಿ ನಾನಿಲ್ಲಿ ಶ್ಲೋಕದಂತೆ ಮಾತ್ರ ಶ್ರೀ ಸೂಕ್ತವನ್ನು ಹೇಳ್ತಾ ಮಹಾದೇವಿ ವಿದ್ಮಹೆ ವಿಷ್ಣು ಪತ್ನಿಚ ಧೀಮಹಿ ತನ್ನೋ ಲಕ್ಷ್ಮಿ ಪ್ರಚೋದಯಾತ್ ಸರಸಿಜ ನಿಲಯೇ ಸರೋಜ ಹಸ್ತೆ ಧವಲ ತರಾಂ ಶುಕ ಗಂಧ ಮಾಲ್ಯ ಶೋಭೆ ಭಗವತಿ ಹರಿ ವಲ್ಲಭೆ ಮನೋಜ್ಞೆ ತ್ರಿಭುವನ ಭೂತಿಕರಿ ಪ್ರಸಿದ ಮಹ್ಯಂ ಪದ್ಮಾಸನಸ್ಥ ವಿಪುಲ ಕಟಿತೀ ಪದ್ಮಪತ್ರಾಯತಾಕ್ಷಿ ಗಂಭೀರ ವರ್ತನಭಿಸ್ತನ ಭರನಮಿತ ಶುಭ್ರ ವಸ್ತ್ರೋತ್ತರಿಯ ಲಕ್ಷ್ಮೀರ್ ದಿವ್ಯರ್ ಗಜೇಂದ್ರೇ ಮಣಿಗಣ ಕಚಿತೇರ್ ಸ್ನಾಪಿತಾ ಹೇಮ ಕುಂಭೈರ್ ನಿತ್ಯಂ ಸಾ ಪದ್ಮಹಸ್ತ ಮಮ ವಸತ ಗೃಹೇ ಸರ್ವ ಮಾಂಗಲ್ಯ ಯುದ್ಧ ಸರ್ವ ಮಂಗಳ ಮಾಂಗಲ್ಯೇ ಶಿವೇ ಸರ್ವಾರ್ಥ ಸಾಧಿಕೆ ಶರಣ್ಯೆ ತ್ರಯಂಬಕೆ ದೇವಿ ನಾರಾಯಣಿ ನಮೋಸ್ತುತೆ ಎಂದು ಶ್ರೀ ಸೂಕ್ತದಿಂದ ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ನಂತರ ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ಈ ನಿರ್ಮಾಲ್ಯ",
      "meaning": "Complete source-audio coverage for nirmālya abhiṣēka with śrī verses.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ಶ್ರೀ ಸೂಕ್ತದಿಂದ ಅಭಿಷೇಕವನ್ನು ಮಾಡುವುದು. ಶ್ರೀ ಸೂಕ್ತವೂ ಕೂಡ ಒಬ್ಬೊಬ್ಬರು ಒಂದೇ ರೀತಿಯಾಗಿ ಉಚ್ಚಾರ ಮಾಡ್ತಾರೆ ಆದ್ದರಿಂದಾಗಿ, ನಾನು ಇಲ್ಲಿ ಶ್ಲೋಕದಂತೆ ಮಾತ್ರ ಶ್ರೀ ಸೂಕ್ತವನ್ನು ಹೇಳ್ತಾ ಇದ್ದೇನೆ. ಮಹಾದೇವ್ಯೈ ಚ ವಿಧ್ಮಹೇ ವಿಷ್ಣುಪತ್ನ್ಯೈ ಚ ಧೀಮಹಿ, ತನ್ನೋ ಲಕ್ಷ್ಮೀಃ ಪ್ರಚೋದಯಾತ್. ಸರಸಿಜನಿಲಯೇ ಸರೋಜಹಸ್ತೇ ಧವಳತರಾಂಶುಕಗಂಧಮಾಲ್ಯಶೋಭೇ, ಭಗವತಿ ಹರಿವಲ್ಲಭೇ ಮನೋಜ್ಞೇ ತ್ರಿಭುವನಭೂತಿಕರಿ ಪ್ರಸೀದ ಮಹ್ಯಂ. ಯಾಸಾ ಪದ್ಮಾಸನಸ್ಥಾ ವಿಪುಲಕಟಿತಟೀ ಪದ್ಮಪತ್ರಾಯತಾಕ್ಷೀ, ಗಂಭೀರಾವರ್ತನಾಭಿಸ್ತನಭರನಮಿತಾ ಶುಭ್ರವಸ್ತ್ರೋತ್ತರೀಯಾ. ಲಕ್ಷ್ಮೀರ್ದಿವ್ಯೈರ್ಗಜೇಂದ್ರೈರ್ಮಣಿಗಣಖಚಿತೈಃ ಸ್ನಾಪಿತಾ ಹೇಮಕುಂಭೈಃ, ನಿತ್ಯಂ ಸಾ ಪದ್ಮಹಸ್ತಾ ಮಮ ವಸತು ಗೃಹೇ ಸರ್ವಮಾಂಗಲ್ಯಯುಕ್ತಾ. ಸರ್ವಮಂಗಳ ಮಾಂಗಲ್ಯೇ ಶಿವೇ ಸರ್ವಾರ್ಥಸಾಧಿಕೇ, ಶರಣ್ಯೇ ತ್ರ್ಯಂಬಕೇ ದೇವಿ ನಾರಾಯಣಿ ನಮೋಸ್ತುತೇ ಎಂದು ಶ್ರೀ ಸೂಕ್ತದಿಂದ ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ನಂತರ. ",
      "captionOriginal": "ಸೂಕ್ತದಿಂದ ಅಭಿಷೇಕವನ್ನು ಮಾಡುವುದು ಶ್ರೀ ಸೂಕ್ತವು ಕೂಡ ಒಬ್ಬೊಬ್ಬರು ಅದೇ ರೀತಿಯಾಗಿ ಉಚ್ಚಾರ ಮಾಡುತ್ತಾರೆ ಆದ್ದರಿಂದಾಗಿ ನಾನಿಲ್ಲಿ ಶ್ಲೋಕದಂತೆ ಮಾತ್ರ ಶ್ರೀ ಸೂಕ್ತವನ್ನು ಹೇಳ್ತಾ ಮಹಾದೇವಿ ವಿದ್ಮಹೆ ವಿಷ್ಣು ಪತ್ನಿಚ ಧೀಮಹಿ ತನ್ನೋ ಲಕ್ಷ್ಮಿ ಪ್ರಚೋದಯಾತ್ ಸರಸಿಜ ನಿಲಯೇ ಸರೋಜ ಹಸ್ತೆ ಧವಲ ತರಾಂ ಶುಕ ಗಂಧ ಮಾಲ್ಯ ಶೋಭೆ ಭಗವತಿ ಹರಿ ವಲ್ಲಭೆ ಮನೋಜ್ಞೆ ತ್ರಿಭುವನ ಭೂತಿಕರಿ ಪ್ರಸಿದ ಮಹ್ಯಂ ಪದ್ಮಾಸನಸ್ಥ ವಿಪುಲ ಕಟಿತೀ ಪದ್ಮಪತ್ರಾಯತಾಕ್ಷಿ ಗಂಭೀರ ವರ್ತನಭಿಸ್ತನ ಭರನಮಿತ ಶುಭ್ರ ವಸ್ತ್ರೋತ್ತರಿಯ ಲಕ್ಷ್ಮೀರ್ ದಿವ್ಯರ್ ಗಜೇಂದ್ರೇ ಮಣಿಗಣ ಕಚಿತೇರ್ ಸ್ನಾಪಿತಾ ಹೇಮ ಕುಂಭೈರ್ ನಿತ್ಯಂ ಸಾ ಪದ್ಮಹಸ್ತ ಮಮ ವಸತ ಗೃಹೇ ಸರ್ವ ಮಾಂಗಲ್ಯ ಯುದ್ಧ ಸರ್ವ ಮಂಗಳ ಮಾಂಗಲ್ಯೇ ಶಿವೇ ಸರ್ವಾರ್ಥ ಸಾಧಿಕೆ ಶರಣ್ಯೆ ತ್ರಯಂಬಕೆ ದೇವಿ ನಾರಾಯಣಿ ನಮೋಸ್ತುತೆ ಎಂದು ಶ್ರೀ ಸೂಕ್ತದಿಂದ ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ನಂತರ ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ಈ ನಿರ್ಮಾಲ್ಯ",
