      "title": "Offering the nirmālya tīrtha",
      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "dēvarige abhiṣēka māḍida ī nirmālya tīrthavannu modalu lakṣmige samarpaṇe māḍuvudu. mahālakṣmyai namaḥ. nirmālyaṁ nivēdayāmi. naṁtara mukhya prāṇanige hanumaṁtanige, haṁ hanumatē namaḥ. nirmālya tīrthaṁ nivēdayāmi. naṁtara nāvu kūḍa mūru bāri nirmālya tīrthavannu svīkāra māḍuvudu. ōṁ viśvāya namaḥ, ōṁ taijasāya namaḥ, ōṁ prājñāya namaḥ, ōṁ turīyāya namaḥ eṁdu bhagavaṁtana nālku nāmagaḷannu smaraṇe māḍtā nāvu nirmālya tīrthavannu svīkāra māḍabēku.",
      "devanagari": "ತೀರ್ಥವನ್ನ ಮೊದಲು ಲಕ್ಷ್ಮಿಗೆ ಸಮರ್ಪಣೆ ಮಾಡುವುದು ಮಹಾಲಕ್ಷ್ಮಿ ನಮಃ ನಿರ್ಮಾಲ್ಯಂ ನಿವೇದಯಾಮಿ ನಂತರ ಮುಖ್ಯ ಪ್ರಾಣನಿಗೆ ಹನುಮಂತನಿಗೆ ಹಂ ಹನುಮತೆ ನಮಃ ನಿರ್ಮಾಲ್ಯ ತೀರ್ಥಂ ನಿವೇದಯಾಮಿ ನಂತರ ನಾವು ಕೂಡ ಮೂರು ಬಾರಿ ನಿರ್ಮಾಲ್ಯ ತೀರ್ಥವನ್ನ ಸ್ವೀಕಾರ ಮಾಡುವುದು ಓಂ ವಿಶ್ವಾಯ ನಮಃ ಓಂ ತೇಜಸಾಯ ನಮಃ ಓಂ ಪ್ರಾಜ್ಞಾಯ ನಮಃ ಓಂ ತುರಿಯಾಯ ನಮಃ ಎಂದು ಭಗವಂತನ ನಾಲಕ್ಕು ನಾಮಗಳನ್ನು ಸ್ಮರಣೆ ಮಾಡುತ್ತಾ ನಾವು ನಿರ್ಮಾಲ್ಯ ತೀರ್ಥವನ್ನು ಸ್ವೀಕಾರ ಮಾಡಬೇಕು ಈ ನಿರ್ಮಾಲ್ಯ",
