      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "modalige dēvarannu, gurugaḷannu prārthane māḍuvudu. nārāyaṇāya paripūrṇaguṇārṇavāya viśvōdayasthitilayōnniyatipradāya jñānapradāya vibhudhāsurasaukhyaduḥkha satkāraṇāya vitatāya namō namastē. yō vipralaṁbhaviparītamatiḥ prabhūta vādān nirasya kr̥tavān bhuvi tattvavādaṁ sarvēśvarō haririti pratipādayaṁtaṁ ānaṁdatīrthamunivaryamahaṁ namāmi. śrīgurubhyō namaḥ, paramagurubhyō namaḥ, mūlagurubhyō namaḥ, ādigurubhyō namaḥ, dēvatāyai namaḥ, śrīvāsudēvāya namaḥ eṁdu. dēvaranna, gurugaḷanna smaraṇe māḍida naṁtara asya śrī puruṣa sūkta mahāmaṁtrasya aṁtaryāmī r̥ṣiḥ, anuṣṭup chaṁdaḥ, antyātriṣṭup chaṁdaḥ, paramapuruṣō dēvatā, puruṣa sūktaṁ maṁtrēṇi bhagavataḥ śrīlakṣmīnārāyaṇasya saṁkṣipta ṣōḍaśōpacāra pūjākṣaṁ karma kariṣyē. eṁdu saṁkalpavannu māḍuvudu.",
      "devanagari": "ದೇವರನ್ನು ಗುರುಗಳನ್ನು ಪ್ರಾರ್ಥನೆ ಮಾಡುವುದು ನಾರಾಯಣಾಯ ಪರಿಪೂರ್ಣ ಗುಣಾರ್ಣವಾಯ ಸ್ಥಿತಿಲಯೋನಿಯತಿ ಪ್ರದಾಯ ಜ್ಞಾನ ಪ್ರದಾಯ ವಿಭುದಾಸುರ ಸೌಖ್ಯ ದುಃಖ ಸತ್ಕಾರಣಾಯ ವಿತಾಯ ನಮೋ ಯೋವಿಪ್ರಲಂಬ ವಿಪರೀತ ಮತಿ ಪ್ರಭುತ ವಾದಾನ್ ನಿರಸ್ಯ ಕೃತವಾನ್ ಭುವಿತತ್ವವಾದಂ ಸರ್ವೇಶ್ವರೋ ಹರಿತಿ ಪ್ರತಿಪಾದಯಂತಂ ಆನಂದ ತೀರ್ಥ ಮುನಿವರಿಯ ಮಹಂ ನಮಾಮಿ ಶ್ರೀ ಗುರುಭ್ಯೋ ನಮಃ ಪರಮ ಗುರುಭ್ಯೋ ನಮಃ ಮೂಲ ಗುರುಭ್ಯೋ ನಮಃ ಆದಿ ಗುರುಭ್ಯೋ ನಮಃ ದೇವತಾಯೇ ನಮಃ ಶ್ರೀ ವಾಸುದೇವಾಯ ನಮಃ ಎಂದು ದೇವರನ್ನು ಗುರುಗಳನ್ನು ಸ್ಮರಣೆ ಮಾಡಿದ ನಂತರ ಅಸ್ಯ ಶ್ರೀ ಪುರುಷ ಸೂಕ್ತ ಮಹಾಮಂತ್ರಸ್ಯ ಅಂತರ್ಯಾಮಿ ಋಷಿಹಿ ಅನುಷ್ಟು ಛಂದಹ ಅಂತ್ಯಪ್ ಛಂದಹ ಪರಮ ಪುರುಷೋ ದೇವತಾ ಪುರುಷ ಸೂಕ್ತ ಮಂತ್ರೈಹಿ ಭಗವತಃ ಶ್ರೀ ಲಕ್ಷ್ಮಿ ನಾರಾಯಣಸ್ಯ ಸಂಕ್ಷಿಪ್ತ ಶೋಡಶೋಪಚಾರ ಪೂಜಾಕ್ಷಂ ಎಂದು ಸಂಕಲ್ಪವನ್ನು ಮಾಡುವುದು ನಂತರ",
