          "text": "nārāyaṇāya paripūrṇaguṇārṇavāya viśvōdayasthitilayōnniyatipradāya jñānapradāya vibhudhāsurasaukhyaduḥkha satkāraṇāya vitatāya namō namastē.\n\nyō vipralaṁbhaviparītamatiḥ prabhūta vādān nirasya kr̥tavān bhuvi tattvavādaṁ sarvēśvarō haririti pratipādayaṁtaṁ ānaṁdatīrthamunivaryamahaṁ namāmi.\n\nśrīgurubhyō namaḥ,\nparamagurubhyō namaḥ,\nmūlagurubhyō namaḥ,\nādigurubhyō namaḥ,\ndēvatāyai namaḥ,\nśrīvāsudēvāya namaḥ"
