      "title": "Dvāra and dīpa devatās; lighting the lamp",
      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "naṁtara dvāra dēvategaḷanna smaraṇe māḍuvudu. śrī śrīyai namaḥ, naṁdaṁ sunaṁdaṁ garuḍaṁ pracaṁḍaṁ caṁḍamēva ca, jayaṁ ca vijayaṁ caiva, kumudaṁ kumudēkṣaṇaṁ, dvāradēvatābhyō namaḥ. naṁtara dīpa dēvategaḷanna smaraṇe māḍuvudu. dīpadēvatābhyō namaḥ. agniṁ dīpavannu beḷagisikoḷḷuvudu. agniṁ prajvalitaṁ vaṁdē, jātavēdaṁ hutāśanaṁ, suraṇāvaraṇa manalaṁ, samiddhaṁ viśvatōmukhaṁ, śrī yajñapuruṣāya namaḥ, paraśurāmāya namaḥ. eṁdu dīpavannu beḷagisikoḷḷuvudu.",
      "devanagari": "ದ್ವಾರ ದೇವತೆಗಳನ್ನು ಸ್ಮರಣೆ ಮಾಡುವುದು ಶ್ರೀ ಶ್ರೀಯ ನಮಃ ನಂದಂ ಸುನಂದಂ ಗರುಡಂ ಪ್ರಚಂಡಮ್ ಚಂಡಮೇವಚ ಜಯಂಚ ವಿಜಯಂ ಚೈವ ಕುಮುದಂ ಕುಮುದೇ ಕ್ಷಣಂ ದ್ವಾರ ದೇವತಾಭ್ಯೋ ನಮಃ ನಂತರ ದೀಪ ದೇವತೆಗಳನ್ನು ಸ್ಮರಣೆ ಮಾಡುವುದು ದೀಪ ನಮಃ ಅಗ್ನಿಮ್ ದೀಪವನ್ನು ಬೆಳಗಿಸಿಕೊಳ್ಳುವುದು ಅಗ್ನಿಂ ಪ್ರಜ್ವ ವಂದೇ ಜಾತ ವೇದಂ ಹುತಾಶನಂ ಸುವರ್ಣ ವರ್ಣ ಮನಲಂ ಸಮಿದ್ಧಂ ವಿಶ್ವತೋಮುಖಂ ಶ್ರೀ ಯಜ್ಞ ಪುರುಷಾಯ ನಮಃ ಪರಶುರಾಮಾಯ ನಮಃ ಎಂದು ಬೆಳಗಿಸಿಕೊಳ್ಳುವುದು ನಂತರ ದೇವರ ಪೂಜೆಗೆ ನಾವು",
      "meaning": "Complete source-audio coverage for dvāra and dīpa devatās; lighting the lamp.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ನಂತರ ದ್ವಾರ ದೇವತೆಗಳನ್ನ ಸ್ಮರಣೆ ಮಾಡುವುದು. ಶ್ರೀ ಶ್ರೀಯೈ ನಮಃ, ನಂದಂ ಸುನಂದಂ ಗರುಡಂ ಪ್ರಚಂಡಂ ಚಂಡಮೇವ ಚ, ಜಯಂ ಚ ವಿಜಯಂ ಚೈವ, ಕುಮುದಂ ಕುಮುದೇಕ್ಷಣಂ, ದ್ವಾರದೇವತಾಭ್ಯೋ ನಮಃ. ನಂತರ ದೀಪ ದೇವತೆಗಳನ್ನ ಸ್ಮರಣೆ ಮಾಡುವುದು. ದೀಪದೇವತಾಭ್ಯೋ ನಮಃ. ಅಗ್ನಿಂ ದೀಪವನ್ನು ಬೆಳಗಿಸಿಕೊಳ್ಳುವುದು. ಅಗ್ನಿಂ ಪ್ರಜ್ವಲಿತಂ ವಂದೇ, ಜಾತವೇದಂ ಹುತಾಶನಂ, ಸುರಣಾವರಣ ಮನಲಂ, ಸಮಿದ್ಧಂ ವಿಶ್ವತೋಮುಖಂ, ಶ್ರೀ ಯಜ್ಞಪುರುಷಾಯ ನಮಃ, ಪರಶುರಾಮಾಯ ನಮಃ. ಎಂದು ದೀಪವನ್ನು ಬೆಳಗಿಸಿಕೊಳ್ಳುವುದು. ",
      "captionOriginal": "ದ್ವಾರ ದೇವತೆಗಳನ್ನು ಸ್ಮರಣೆ ಮಾಡುವುದು ಶ್ರೀ ಶ್ರೀಯ ನಮಃ ನಂದಂ ಸುನಂದಂ ಗರುಡಂ ಪ್ರಚಂಡಮ್ ಚಂಡಮೇವಚ ಜಯಂಚ ವಿಜಯಂ ಚೈವ ಕುಮುದಂ ಕುಮುದೇ ಕ್ಷಣಂ ದ್ವಾರ ದೇವತಾಭ್ಯೋ ನಮಃ ನಂತರ ದೀಪ ದೇವತೆಗಳನ್ನು ಸ್ಮರಣೆ ಮಾಡುವುದು ದೀಪ ನಮಃ ಅಗ್ನಿಮ್ ದೀಪವನ್ನು ಬೆಳಗಿಸಿಕೊಳ್ಳುವುದು ಅಗ್ನಿಂ ಪ್ರಜ್ವ ವಂದೇ ಜಾತ ವೇದಂ ಹುತಾಶನಂ ಸುವರ್ಣ ವರ್ಣ ಮನಲಂ ಸಮಿದ್ಧಂ ವಿಶ್ವತೋಮುಖಂ ಶ್ರೀ ಯಜ್ಞ ಪುರುಷಾಯ ನಮಃ ಪರಶುರಾಮಾಯ ನಮಃ ಎಂದು ಬೆಳಗಿಸಿಕೊಳ್ಳುವುದು ನಂತರ ದೇವರ ಪೂಜೆಗೆ ನಾವು",
      "losslessRoman": "naṁtara dvāra dēvategaḷanna smaraṇe māḍuvudu. śrī śrīyai namaḥ, naṁdaṁ sunaṁdaṁ garuḍaṁ pracaṁḍaṁ caṁḍamēva ca, jayaṁ ca vijayaṁ caiva, kumudaṁ kumudēkṣaṇaṁ, dvāradēvatābhyō namaḥ. naṁtara dīpa dēvategaḷanna smaraṇe māḍuvudu. dīpadēvatābhyō namaḥ. agniṁ dīpavannu beḷagisikoḷḷuvudu. agniṁ prajvalitaṁ vaṁdē, jātavēdaṁ hutāśanaṁ, suraṇāvaraṇa manalaṁ, samiddhaṁ viśvatōmukhaṁ, śrī yajñapuruṣāya namaḥ, paraśurāmāya namaḥ. eṁdu dīpavannu beḷagisikoḷḷuvudu.",
