      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ನಂತರ ದೇವರ ಪೂಜೆಗೆ ನಾವು ತುಳಸಿಯನ್ನು, ಹೂವನ್ನು ಶೇಖರಣೆ ಮಾಡಿಕೊಂಡು ಕೊಳ್ಳುವುದು. ನಾವು ಕದ್ದ ತುಳಸಿ ಪುಷ್ಪಗಳನ್ನು ದೇವರಿಗೆ ಅರ್ಪಣೆ ಮಾಡಬಾರದು. ಎಲ್ಲೋ ವಾಕಿಂಗ್ ಹೋಗ್ತಾ ಯಾರದೋ ಮನೆಯ ಮುಂದೆ ಬೆಳಗ ನಾವು ಹೂಗಳನ್ನು ಅವರಿಗೆ ಗೊತ್ತಿಲ್ಲದಂತೆ ಕಿತ್ಕೊಂಡು ಬರೋದು, ಜಗಳ ಆಡಿ ಕಿತ್ಕೊಂಡು ಬಂದು ನಾವು ದೇವರ ಪೂಜೆನ ಮಾಡಬಾರದು. ನಮಗೇ ಎಷ್ಟು ಸಾಧ್ಯವೋ, ಕೊಂಡ ಪುಷ್ಪಗಳನ್ನು ಪೂಜೆ ಮಾಡಬಾರದು ಅಂತ ಹೇಳ್ತಾರೆ. ಆಗಲಿ, ಆ ಕೊಂಡ ಪುಷ್ಪಗಳನ್ನು ತಂದ ನಂತರ ಒಮ್ಮೆ ಶಂಖದ ನೀರಿನಿಂದ ಪ್ರೋಕ್ಷಣೆ ಮಾಡಿಕೊಳ್ಳುವುದು. ನಂತರ ದೇವರ ಪೂಜೆಗೆ ಉಪಕ್ರಮಿಸುವುದು ಗಂಟಾನಾದವನ್ನು ಮಾಡುವುದು. ಮುಖ್ಯ ಪ್ರಾಣಾಯ ನಮಃ, ಅಖಂಡಾಶ್ಮಾಯ ನಮಃ ಎಂದು ಗಂಟೆಯನ್ನು ನುಡಿಸುವುದು. ",
