      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "āmēle tuḷasiyannu prārthane māḍuvudu. prasīda tuḷasi dēvi, prasīda harivallabhē, kṣīrōdamathanōdbhūtē, tuḷasi tvāṁ namāmyahaṁ. dēvara pūjege tuḷasi bahaḷa mukhya. maneyalli giḍa beḷesalikke īgina kāladalli namage avakāśa irōdilla. anukūla iddavaru khaṁḍita tuḷasiyannu beḷesi, tuḷasiyannu dēvara pūjege baḷasuvudu. ādare bāḍige manegaḷalliruvavaru tuḷasi sigadē iddāga kēvala tuḷasiyannu smaraṇe māḍikoḷḷuvudu, śrī tuḷasyai namaḥ aṁta tuḷasiyannu smaraṇe māḍuttā dēvara pūje māḍuvudu. dēvaru bhaktige valitāne, ādare sōmāritana māḍabāradu.",
