      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ಆಮೇಲೆ ತುಳಸಿಯನ್ನು ಪ್ರಾರ್ಥನೆ ಮಾಡುವುದು. ಪ್ರಸೀದ ತುಳಸಿ ದೇವಿ, ಪ್ರಸೀದ ಹರಿವಲ್ಲಭೇ, ಕ್ಷೀರೋದಮಥನೋದ್ಭೂತೇ, ತುಳಸಿ ತ್ವಾಂ ನಮಾಮ್ಯಹಂ. ದೇವರ ಪೂಜೆಗೆ ತುಳಸಿ ಬಹಳ ಮುಖ್ಯ. ಮನೆಯಲ್ಲಿ ಗಿಡ ಬೆಳೆಸಲಿಕ್ಕೆ ಈಗಿನ ಕಾಲದಲ್ಲಿ ನಮಗೆ ಅವಕಾಶ ಇರೋದಿಲ್ಲ. ಅನುಕೂಲ ಇದ್ದವರು ಖಂಡಿತ ತುಳಸಿಯನ್ನು ಬೆಳೆಸಿ, ತುಳಸಿಯನ್ನು ದೇವರ ಪೂಜೆಗೆ ಬಳಸುವುದು. ಆದರೆ ಬಾಡಿಗೆ ಮನೆಗಳಲ್ಲಿರುವವರು ತುಳಸಿ ಸಿಗದೇ ಇದ್ದಾಗ ಕೇವಲ ತುಳಸಿಯನ್ನು ಸ್ಮರಣೆ ಮಾಡಿಕೊಳ್ಳುವುದು, ಶ್ರೀ ತುಳಸ್ಯೈ ನಮಃ ಅಂತ ತುಳಸಿಯನ್ನು ಸ್ಮರಣೆ ಮಾಡುತ್ತಾ ದೇವರ ಪೂಜೆ ಮಾಡುವುದು. ದೇವರು ಭಕ್ತಿಗೆ ವಲಿತಾನೆ, ಆದರೆ ಸೋಮಾರಿತನ ಮಾಡಬಾರದು.",
      "captionOriginal": "ತುಳಸಿಯನ್ನು ಪ್ರಾರ್ಥನೆ ಮಾಡುವುದು ಪ್ರಸಿದ್ಧ ತುಳಸಿ ದೇವಿ ಪ್ರಸಿದ್ಧ ಹರಿವಲ್ಲಭೆ ಕ್ಷೀರೋದನೋದ್ಭೂತೆ ತುಳಸಿ ನಮಾಮ್ಯಂ ದೇವರ ಪೂಜೆಗೆ ತುಳಸಿ ಬಹಳ ಮುಖ್ಯ ಮನೆಯಲ್ಲಿ ಗಿಡ ಬೆಳೆಸಲಿಕ್ಕೆ ಈಗಿನ ಕಾಲದಲ್ಲಿ ನಮಗೆ ಅವಕಾಶ ಇರೋದಿಲ್ಲ ಅನುಕೂಲ ಇದ್ದವರು ಖಂಡಿತ ತುಳಸಿಯನ್ನು ಬೆಳೆಸಿ ತುಳಸಿಯನ್ನು ದೇವರ ಪೂಜೆಗೆ ಬಳಸುವುದು ಆದರೆ ಬಾಡಿಗೆ ಮನೆಗಳಲ್ಲಿ ಇರುವವರು ತುಳಸಿ ಸಿಗದೆ ಇದ್ದಾಗ ಕೇವಲ ತುಳಸಿಯನ್ನು ಸ್ಮರಣೆ ಮಾಡಿಕೊಳ್ಳುವುದು ಶ್ರೀ ತುಳಸಿಯೇ ನಮಃ ಅಂತ ತುಳಸಿಯನ್ನು ಸ್ಮರಣೆ ಮಾಡುತ್ತಾ ದೇವರ ಪೂಜೆ ಮಾಡುವುದು ದೇವರು ಭಕ್ತಿಗೆ ಒಲಿತಾನೆ ಆದರೆ ಸೋಮಾರಿತನ ಮಾಡಬಾರದು",
      "losslessRoman": "āmēle tuḷasiyannu prārthane māḍuvudu. prasīda tuḷasi dēvi, prasīda harivallabhē, kṣīrōdamathanōdbhūtē, tuḷasi tvāṁ namāmyahaṁ. dēvara pūjege tuḷasi bahaḷa mukhya. maneyalli giḍa beḷesalikke īgina kāladalli namage avakāśa irōdilla. anukūla iddavaru khaṁḍita tuḷasiyannu beḷesi, tuḷasiyannu dēvara pūjege baḷasuvudu. ādare bāḍige manegaḷalliruvavaru tuḷasi sigadē iddāga kēvala tuḷasiyannu smaraṇe māḍikoḷḷuvudu, śrī tuḷasyai namaḥ aṁta tuḷasiyannu smaraṇe māḍuttā dēvara pūje māḍuvudu. dēvaru bhaktige valitāne, ādare sōmāritana māḍabāradu.",
