      "originalScript": "ನಂತರ ಶಂಖ ಪೂಜೆಯನ್ನು ಮಾಡುವುದು. ಶಂಖ ಪೂಜೆಯನ್ನು ಶಂಖದಲ್ಲಿ ಸ್ವಲ್ಪ ನೀರನ್ನು ತುಂಬಿಕೊಂಡು, ಎಂಟು ಬಾರಿ ನಾರಾಯಣ ಅಷ್ಟಾಕ್ಷರ ಮಂತ್ರವನ್ನು ಪಠಿಸುವುದು. ಇದೇ ಶಂಖ ಪೂಜೆ ವಿಸ್ತಾರವಾಗಿದೆ, ಇಲ್ಲಿ ಸಂಕ್ಷಿಪ್ತವಾಗಿ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಯವಂ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಯವಂ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಯವಂ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಯವಂ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಯವಂ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಯವಂ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಯವಂ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಯವಂ. ಅನಯಾ ಶಂಖ ಪೂಜಯಾ ಗೋಪಾಲಕೃಷ್ಣಃ ಪ್ರೀಯತಾಂ, ಪ್ರೀತಃ ವರದೋ ಭವತು ಶ್ರೀಕೃಷ್ಣಾರ್ಪಣಮಸ್ತು. ",
