      "mantra": "īga kalaśa pūje māḍuvudu. eraḍu kalaśagaḷannu sthāpisikoṁḍu, adaralli oṁdu kalaśadalli tuḷasi kāṣṭhavannu tēdu mātra adannu berasabēku nīrinalli. innoṁdu kalaśadalli kēsari, paccakarpūra, gaṁdhavannu tēdu adara miśraṇavannu nāvu beresikoḷḷuvudu idannu pūrṇakuṁbha aṁta hēḷtāre. eraḍu kalaśagaḷigū kūḍa gaṁdhadiṁda alaṁkāra māḍuvudu, gaṁdha haccōdu. adakke samaya illadē iddāga kēvala nīriniṁdalē abhiṣēka māḍuvudu. kalaśa pūjene māḍabēku. kalaśadallū bhagavaṁtana nūreṁṭu rūpagaḷannu nāvu dhyāna māḍabēku. ādare avakāśa illadē iddāga ī kalaśavannu muṭṭikoṁḍu ī ślōka hēḷōdu: ēkapaṁcāśadvarṇānāṁ caturviṁśati mūrtayaḥ ātmādyā vāsudēvādyā viśvādyā matsya kacchapau, kōlōn r̥ṣiṁmaśca baṭuḥ, jāmadagnya raghūdvahaḥ, vāsiṣṭhō yādavō kr̥ṣṇaḥ, ātrēyō buddhaḥ kalkinau. aṁta ī ślōkavannu paṭhaṇa māḍi hadināru bāri nārāyaṇa aṣṭākṣara maṁtravannu japa māḍuvudu. ōṁ ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ, ōṁ namō nārāyaṇāya. ōṁ. kalaśadalli tuḷasiyannu hākirabēku. naṁtara anēna kalaśa pūjā karmaṇā madhyvāṁtargataḥ gōpālakr̥ṣṇaḥ prīyatāṁ, prītaḥ varadō bhavatu eṁdu kr̥ṣṇārpaṇavannu biḍabēku.",
