      "originalScript": "ಈಗ ಆವಾಹನ. ಆವಾಹನ ನಮ್ಮ ಹೃದಯ ಕಮಲದಲ್ಲಿ ಇರುವ ದೇ ಬಿಂಬರೂಪಿಯಾದ ದೇವರನ್ನ, ನಾವು ಉಸಿರಿನ ಮೂಲಕ, ಬಲಭಾಗದ ಉಸಿರಿನ ಮೂಲಕ ಪ್ರತಿಮೆಯಲ್ಲಿ ತಂದು ದೇವರನ್ನ ಕೂಡು ಎಂದು ಪ್ರಾರ್ಥನೆ ಮಾಡುವುದು. ಇದನ್ನೇ ಆವಾಹನ ಅಂತ ಕರೀತಾರೆ. ಅದಕ್ಕಿಂತ ಮೊದಲು ಮಾನಸ ಪೂಜೆಯನ್ನು ಮಾಡಬೇಕು. ಇನ್ನೊಬ್ಬರ ಮನೆಯಲ್ಲಿ ಪೂಜೆ ಏನ ಮಾಡಬೇಕಾದ್ರೆ, ಸೂರ್ಯ ಮಂಡಲದಿಂದ ನಾರಾಯಣನನ್ನ ಪ್ರತಿಮೆಯ ಮಧ್ಯೆ ಆವಾಹನೆ ಮಾಡುವುದು. ಮೊದಲು ನಮ್ಮ ಹೃದಯ ಕಮಲದಲ್ಲಿರುವ ದೇವರನ್ನ ಧ್ಯಾನ ಮಾಡುವುದು. ಹೃದಯ ಕಮಲದಲ್ಲಿರುವ ಬಿಂಬರೂಪಿಯಾದ ದೇವರನ್ನ, ನಾರಾಯಣನನ್ನ ಧ್ಯಾನ ಮಾಡುವುದು. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ. ಏಹಿ ಏಹಿ ಮಮ ಹೃತ್ಪದ್ಮಸ್ಥಿತಃ ಶ್ರೀಪುರುಷೋತ್ತಮ, ಆವಾಹಯಾಮಿ ಪೀಠೇ ತ್ವಾಂ ಪ್ರತಿಮಾಯಾಂ ಸನ್ನಿಧೌ ಭವ. ಓಂ ಸಹಸ್ರಶೀರ್ಷಾ ಪುರುಷಃ ಸಹಸ್ರಾಕ್ಷಃ ಸಹಸ್ರಪಾತ್, ಸ ಭೂಮಿಂ ವಿಶ್ವತೋ ವೃತ್ವಾ ಅತ್ಯತಿಷ್ಠದ್ದಶಾಂಗುಲಂ. ಎಂದು ಬಲ ಮೂಗಿನ ಹೊಳ್ಳೆಯ ಮೂಲಕ, ಉಸಿರಿನ ಮೂಲಕ ದೇವರು ಹೂ ತುಳಸಿಗಳ ಮೂಲಕ ಪ್ರತಿಮೆಯಲ್ಲಿ ಬಂದು ಕೂಡ್ತಾ ಇದ್ದಾನೆ ಅಂತ, ಇದು ಆವಾಹನ ಮುದ್ರೆ. ಆ ತುಳಸಿಯನ್ನು ದೇವರಿಗೆ ಅರ್ಪಣೆ ಮಾಡಿ ಹತ್ತು ಬಾರಿ ನಾರಾಯಣ ಅಷ್ಟಾಕ್ಷರ ಮಂತ್ರವನ್ನು ಜಪ ಮಾಡುವುದು. ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ",
