      "losslessRoman": "īga āvāhana. āvāhana namma hr̥daya kamaladalli iruva dē biṁbarūpiyāda dēvaranna, nāvu usirina mūlaka, balabhāgada usirina mūlaka pratimeyalli taṁdu dēvaranna kūḍu eṁdu prārthane māḍuvudu. idannē āvāhana aṁta karītāre. adakkiṁta modalu mānasa pūjeyannu māḍabēku. innobbara maneyalli pūje ēna māḍabēkādre, sūrya maṁḍaladiṁda nārāyaṇananna pratimeya madhye āvāhane māḍuvudu. modalu namma hr̥daya kamaladalliruva dēvaranna dhyāna māḍuvudu. hr̥daya kamaladalliruva biṁbarūpiyāda dēvaranna, nārāyaṇananna dhyāna māḍuvudu. ōṁ ōṁ namō nārāyaṇāya ōṁ. ēhi ēhi mama hr̥tpadmasthitaḥ śrīpuruṣōttama, āvāhayāmi pīṭhē tvāṁ pratimāyāṁ sannidhau bhava. ōṁ sahasraśīrṣā puruṣaḥ sahasrākṣaḥ sahasrapāt, sa bhūmiṁ viśvatō vr̥tvā atyatiṣṭhaddaśāṁgulaṁ. eṁdu bala mūgina hoḷḷeya mūlaka, usirina mūlaka dēvaru hū tuḷasigaḷa mūlaka pratimeyalli baṁdu kūḍtā iddāne aṁta, idu āvāhana mudre. ā tuḷasiyannu dēvarige arpaṇe māḍi hattu bāri nārāyaṇa aṣṭākṣara maṁtravannu japa māḍuvudu. ōṁ namō nārāyaṇāya yava, ōṁ namō nārāyaṇāya yavaṁ, ōṁ namō nārāyaṇāya yavaṁ, ōṁ namō nārāyaṇāya yavaṁ, ōṁ namō nārāyaṇāya yavaṁ, ōṁ namō nārāyaṇāya yavaṁ, ōṁ namō nārāyaṇāya yavaṁ, ōṁ namō nārāyaṇāya yavaṁ, ōṁ namō nārāyaṇāya yavaṁ, ōṁ namō nārāyaṇāya yavaṁ.",
