      "devanagari": "ಮಾಡುವುದು ಓಂ ಲಂ ಲಕ್ಷ್ಮಿ ನಮಃ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಮುಖ್ಯ ಪ್ರಾಣನ ಪ್ರತಿಮೆಯಲ್ಲೂ ಕೂಡ ಆವಾಹನೆ ಮಾಡುವುದು ಓಂ ಹಂ ಹನುಮತೇ ನಮಃ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಗರುಡ ಮತ್ತು ಶೇಷ ದೇವರ ಪ್ರತಿಮೆಗಳಿದ್ದರೆ ಅದನ್ನು ಮುಟ್ಟಿಕೊಂಡು ಓಂ ಶ್ರೀಮ್ ಶೇಷಾಯ ನಮಃ ಓಂ ಗಂ ಗರುಡಾಯ ನಮಃ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಅಂತ ಅವರಿಬ್ಬರನ್ನು ಆವಾಹನೆ ಮಾಡಿ ನಮ್ಮಲ್ಲೂ ಕೂಡ ದೇವರಿದ್ದಾನೆ ದೇವರೇ ಈ ಪೂಜೆಗೆ ಬೇಕಾದ ಮನಸ್ಸನ್ನ ಪಕ್ವಗೊಳಿಸುತ್ತಾನೆ ಅಂತ ಭಾವಿಸಿ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಎಂದು ಸ್ಮರಣೆ ಮಾಡುತ್ತಾ ತುಳಸಿಯನ್ನ ಆಗ್ರಹಣೆ ಮಾಡಿ ಕಣ್ಣಿಗೆ ಒತ್ತುಕೊಂಡು ಅರ್ಘ್ಯ",
      "meaning": "Complete source-audio coverage for āvāhana in the conch and attendant deities.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ಮತ್ತೆ ಶಂಖದಲ್ಲೂ ಕೂಡ ಲಕ್ಷ್ಮಿಯನ್ನು ಆವಾಹನೆ ಮಾಡುವುದು. ಓಂ ಲಂ ಲಕ್ಷ್ಮೀ ನಮಃ. ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಮುಖ್ಯ ಪ್ರಾಣನ ಪ್ರತಿಮೆಯಲ್ಲೂ ಕೂಡ ಆವಾಹನೆ ಮಾಡುವುದು. ಓಂ ಹಂ ಹನುಮತೇ ನಮಃ. ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಗರುಡ ಮತ್ತು ಶೇಷದೇವರ ಪ್ರತಿಮೆಗಳಿದ್ದರೆ ಅದನ್ನು ಮುಟ್ಟಿಕೊಂಡು, ಓಂ ಶೇಂ ಶೇಷಾಯ ನಮಃ, ಓಂ ಗಂ ಗರುಡಾಯ ನಮಃ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ ಅಂತ ಅವರಿಬ್ಬರನ್ನೂ ಆವಾಹನೆ ಮಾಡಿ. ನಮ್ಮಲ್ಲೂ ಕೂಡ ದೇವರಿದ್ದಾನೆ, ದೇವರೇ ಈ ಪೂಜೆಗೆ ಬೇಕಾದ ಮನಸ್ಸನ್ನು ಪಕ್ವಗೊಳಿಸ್ತಾನೆ ಅಂತ ಭಾವಿಸಿ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ ಎಂದು ಸ್ಮರಣೆ ಮಾಡ್ತಾ ಆ ತುಳಸಿಯನ್ನು ಆಗ್ರಹಣೆ ಮಾಡಿ, ಕಣ್ಣುಗೊತ್ತುಕೊಂಡು ಅರ್ಘ್ಯಪಾತ್ರೆಯಲ್ಲಿ ಬಿಟ್ಟುಬಿಡುವುದು. ",
