      "mantra": "ētāvānasya mahimā tō jyāyāṁśca puruṣaḥ| pādō'sya viśvā bhūtāni tripādasyāmr̥taṁ divi| ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmīnārāyaṇāya pādāravindayōḥ pādyaṁ samarpayāmi| eṁdu dēvara kālige pādyavannu samarpaṇe māḍuvudu. hīge dēvarige āsanavannu samarpaṇe māḍida naṁtara, dēvara kālu toḷeyōdakke nīrannu samarpaṇe māḍuvudannē pādya aṁta hēḷtāre. ētāvānasya mahimā atō jyāyāṁśca puruṣaḥ| pādō'sya viśvā bhūtāni tripādasyāmr̥taṁ divi| ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmīnārāyaṇāya pādāravindayōḥ pādyaṁ samarpayāmi|",
      "devanagari": "ದಿವಿ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ಪಾದಾರವಿಂದಯೋಹೋ ಪಾದ್ಯಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು ದೇವರ ಕಾಲಿಗೆ ಪಾದ್ಯವನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು ಹೀಗೆ ದೇವರಿಗೆ ಆಸನವನ್ನು ಸಮರ್ಪಣೆ ಮಾಡಿದ ನಂತರ ದೇವರ ಕಾಲು ತೊಳೆಯುವುದಕ್ಕೆ ನೀರನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದನ್ನೇ ಪಾದ್ಯ ಅಂತ ಹೇಳುತ್ತಾರೆ ಏತಾವಾನಸ್ಯ ಮಹಿಮಾ ಅತೋಜಾಯಂ ಚಪುರುಷಃ ಪಾದೋಸ್ಯ ವಿಶ್ವ ಭೂತಾನಿ ದೇವಿ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಪಾದಾರವಿಂದಯೋಹೋ ಪಾದ್ಯಂ",
      "meaning": "Complete source-audio coverage for pādya.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "एतावानस्य महिमा तो ज्यायांश्च पुरुषः। पादोऽस्य विश्वा भूतानि त्रिपादस्यामृतं दिवि। ॐ ओं नमो नारायणाय, ॐ श्रीलक्ष्मीनारायणाय पादारविन्दयोः पाद्यं समर्पयामि। ಎಂದು ದೇವರ ಕಾಲಿಗೆ ಪಾದ್ಯವನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು. ಹೀಗೆ ದೇವರಿಗೆ ಆಸನವನ್ನು ಸಮರ್ಪಣೆ ಮಾಡಿದ ನಂತರ, ದೇವರ ಕಾಲು ತೊಳೆಯೋದಕ್ಕೆ ನೀರನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದನ್ನೇ ಪಾದ್ಯ ಅಂತ ಹೇಳ್ತಾರೆ. एतावानस्य महिमा अतो ज्यायांश्च पुरुषः। पादोऽस्य विश्वा भूतानि त्रिपादस्यामृतं दिवि। ॐ ओं नमो नारायणाय, ॐ श्रीलक्ष्मीनारायणाय पादारविन्दयोः पाद्यं समर्पयामि। ",
