      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "ācamanavannu arpaṇe māḍida naṁtara snāna. modalige gaṁdhōdakavannu berasada kēvala tuḷasi kāṣṭhavannu mātra beresida nīranna tegedukoṁḍu dēvarige abhiṣēka māḍuvudu. yat puruṣēṇa haviṣā dēvā yajñamatanvata, vasaṁtō asyāsīdājyaṁ, grīṣma idhmaḥ śarad dhaviḥ. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmī nārāyaṇāya snānaṁ samarpayāmi. naṁtara gaṁṭānādada mūlaka gaṁdhōdakavannu miśraṇa māḍida nīrannu tegedukoṁḍu īga kalaśadiṁda alla, śaṁkhadiṁda alla, nēra kalaśadiṁdalē abhiṣēka māḍuvudu. ā kalaśavannu śaṁkhakke muṭṭisi, agnimīḷe purōhitaṁ yajñasya dēvaṁ r̥tvijaṁ, hōtāraṁ ratnadhātamaṁ eṁdu abhiṣēka māḍuvudu. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmī nārāyaṇāya snānānaṁtaraṁ punarācamanīyaṁ samarpayāmi eṁdu dēvarige tōrisi arghyapātreyalli nīrannu samarpaṇe māḍuvudu. īga dēvarige abhiṣēka māḍida tīrthadiṁda lakṣmigū kūḍa abhiṣēka māḍuvudu.",
      "devanagari": "ಸ್ನಾನ ಮೊದಲಿಗೆ ಬೆರೆಸದ ಕೇವಲ ತುಳಸಿ ಕಾಷ್ಟವನ್ನು ಮಾತ್ರ ಬೆರೆಸಿದ ನೀರನ್ನು ತೆಗೆದುಕೊಂಡು ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡುವುದು ಯತ್ಪುರುಷೇಣ ಹವಿಷ ಯಜ್ಞಮತನ್ವತ ವಸಂತೋ ಅಸ್ಯ ಸೀದಾಜ್ಯಂ ಗ್ರೀಷ್ಮ ಇದ್ವ ಶರದ್ಧವಿಹಿ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಸ್ನಾನಂ ಸಮರ್ಪಯಾಮಿ ನಂತರ ಗಂಟಾನಾದದ ಮೂಲಕ ಗಂಧೋದಕವನ್ನು ಮಿಶ್ರಣ ಮಾಡಿದ ನೀರನ್ನ ತೆಗೆದುಕೊಂಡು ಈಗ ಕಲಶದಿಂದ ಅಲ್ಲ ಶಂಖದಿಂದ ಅಲ್ಲ ನೇರ ಕಲಶದಿಂದಲೇ ಅಭಿಷೇಕ ಮಾಡುವುದು ಆ ಕಲಶವನ್ನು ಶಂಖಕ್ಕೆ ಮೃತ್ವಿಜಂ ಹೋತಾರಂ ರತ್ನ ಧಾತಮಂ ಎಂದು ಅಭಿಷೇಕ ಮಾಡುವುದು ನಾರಾಯಣಾಯ ಸ್ನಾನಾನಂತರಂ ಪುನರಾಚಮನೀಯಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು ದೇವರಿಗೆ ತೋರಿಸಿ ಅರ್ಘ್ಯ ಪಾತ್ರೆಯಲ್ಲಿ ನೀರನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು ಈಗ",
      "meaning": "Complete source-audio coverage for snāna and abhiṣēka.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ಆಚಮನವನ್ನು ಅರ್ಪಣೆ ಮಾಡಿದ ನಂತರ ಸ್ನಾನ. ಮೊದಲಿಗೆ ಗಂಧೋದಕವನ್ನು ಬೆರಸದ ಕೇವಲ ತುಳಸಿ ಕಾಷ್ಠವನ್ನು ಮಾತ್ರ ಬೆರೆಸಿದ ನೀರನ್ನ ತೆಗೆದುಕೊಂಡು ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡುವುದು. ಯತ್ ಪುರುಷೇಣ ಹವಿಷಾ ದೇವಾ ಯಜ್ಞಮತನ್ವತ, ವಸಂತೋ ಅಸ್ಯಾಸೀದಾಜ್ಯಂ, ಗ್ರೀಷ್ಮ ಇಧ್ಮಃ ಶರದ್ ಧವಿಃ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಓಂ ಶ್ರೀಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಸ್ನಾನಂ ಸಮರ್ಪಯಾಮಿ. ನಂತರ ಗಂಟಾನಾದದ ಮೂಲಕ ಗಂಧೋದಕವನ್ನು ಮಿಶ್ರಣ ಮಾಡಿದ ನೀರನ್ನು ತೆಗೆದುಕೊಂಡು ಈಗ ಕಲಶದಿಂದ ಅಲ್ಲ, ಶಂಖದಿಂದ ಅಲ್ಲ, ನೇರ ಕಲಶದಿಂದಲೇ ಅಭಿಷೇಕ ಮಾಡುವುದು. ಆ ಕಲಶವನ್ನು ಶಂಖಕ್ಕೆ ಮುಟ್ಟಿಸಿ, ಅಗ್ನಿಮೀಳೆ ಪುರೋಹಿತಂ ಯಜ್ಞಸ್ಯ ದೇವಂ ಋತ್ವಿಜಂ, ಹೋತಾರಂ ರತ್ನಧಾತಮಂ ಎಂದು ಅಭಿಷೇಕ ಮಾಡುವುದು. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಓಂ ಶ್ರೀಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಸ್ನಾನಾನಂತರಂ ಪುನರಾಚಮನೀಯಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು ದೇವರಿಗೆ ತೋರಿಸಿ ಅರ್ಘ್ಯಪಾತ್ರೆಯಲ್ಲಿ ನೀರನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು. ಈಗ ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ತೀರ್ಥದಿಂದ ಲಕ್ಷ್ಮಿಗೂ ಕೂಡ ಅಭಿಷೇಕ ಮಾಡುವುದು.",
      "captionOriginal": "ಸ್ನಾನ ಮೊದಲಿಗೆ ಬೆರೆಸದ ಕೇವಲ ತುಳಸಿ ಕಾಷ್ಟವನ್ನು ಮಾತ್ರ ಬೆರೆಸಿದ ನೀರನ್ನು ತೆಗೆದುಕೊಂಡು ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡುವುದು ಯತ್ಪುರುಷೇಣ ಹವಿಷ ಯಜ್ಞಮತನ್ವತ ವಸಂತೋ ಅಸ್ಯ ಸೀದಾಜ್ಯಂ ಗ್ರೀಷ್ಮ ಇದ್ವ ಶರದ್ಧವಿಹಿ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಸ್ನಾನಂ ಸಮರ್ಪಯಾಮಿ ನಂತರ ಗಂಟಾನಾದದ ಮೂಲಕ ಗಂಧೋದಕವನ್ನು ಮಿಶ್ರಣ ಮಾಡಿದ ನೀರನ್ನ ತೆಗೆದುಕೊಂಡು ಈಗ ಕಲಶದಿಂದ ಅಲ್ಲ ಶಂಖದಿಂದ ಅಲ್ಲ ನೇರ ಕಲಶದಿಂದಲೇ ಅಭಿಷೇಕ ಮಾಡುವುದು ಆ ಕಲಶವನ್ನು ಶಂಖಕ್ಕೆ ಮೃತ್ವಿಜಂ ಹೋತಾರಂ ರತ್ನ ಧಾತಮಂ ಎಂದು ಅಭಿಷೇಕ ಮಾಡುವುದು ನಾರಾಯಣಾಯ ಸ್ನಾನಾನಂತರಂ ಪುನರಾಚಮನೀಯಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು ದೇವರಿಗೆ ತೋರಿಸಿ ಅರ್ಘ್ಯ ಪಾತ್ರೆಯಲ್ಲಿ ನೀರನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು ಈಗ",
      "losslessRoman": "ācamanavannu arpaṇe māḍida naṁtara snāna. modalige gaṁdhōdakavannu berasada kēvala tuḷasi kāṣṭhavannu mātra beresida nīranna tegedukoṁḍu dēvarige abhiṣēka māḍuvudu. yat puruṣēṇa haviṣā dēvā yajñamatanvata, vasaṁtō asyāsīdājyaṁ, grīṣma idhmaḥ śarad dhaviḥ. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmī nārāyaṇāya snānaṁ samarpayāmi. naṁtara gaṁṭānādada mūlaka gaṁdhōdakavannu miśraṇa māḍida nīrannu tegedukoṁḍu īga kalaśadiṁda alla, śaṁkhadiṁda alla, nēra kalaśadiṁdalē abhiṣēka māḍuvudu. ā kalaśavannu śaṁkhakke muṭṭisi, agnimīḷe purōhitaṁ yajñasya dēvaṁ r̥tvijaṁ, hōtāraṁ ratnadhātamaṁ eṁdu abhiṣēka māḍuvudu. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmī nārāyaṇāya snānānaṁtaraṁ punarācamanīyaṁ samarpayāmi eṁdu dēvarige tōrisi arghyapātreyalli nīrannu samarpaṇe māḍuvudu. īga dēvarige abhiṣēka māḍida tīrthadiṁda lakṣmigū kūḍa abhiṣēka māḍuvudu.",
