      "title": "Abhiṣēka for Lakṣmī and the attendant deities",
      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "ōṁ ōṁ namō nārāyaṇāya ōṁ śrīlakṣmī nārāyaṇāya snānānaṁtaraṁ punarācamanīyaṁ samarpayāmi eṁdu dēvarige tōrisi arghyapātreyalli nīrannu samarpaṇe māḍuvudu. īga dēvarige abhiṣēka māḍida tīrthadiṁda lakṣmigū kūḍa abhiṣēka māḍuvudu. sarvamaṁgala māṁgalyē śivē sarvārthasādhikē śaraṇyē tryaṁbakē dēvi nārāyaṇi namōstutē. naṁtara hanumaṁtanige abhiṣēka. hanumaṁtana yāvudādarū stōtravannu kūḍa hēḷikoṁḍu abhiṣēka māḍabahudu. ōṁ udyadravi prakarasannibhamacyutāṁkē svāsīnamasyanutinityavacaḥ pravr̥ttiṁ jñāyēdgadā bhayakaraṁ sakr̥tāṁjaliṁ taṁ prāṇaṁ yathēṣṭatanumunnatakarmaśaktiṁ. mukhya prāṇanige, hanumaṁtanige abhiṣēka māḍida nīrannu pratyēka pātreyalli saṁgraha māḍuvudu. hāge garuḍa, śēṣa, yāra pratime iddarū kūḍa dēvarige abhiṣēka māḍida nīriniṁda. avaru kūḍa snāna māḍisuvudu, ā nīrannu arghyapātreyalli saṁgraha māḍikoḷḷuvudu. mukhya prāṇana tīrthavannu bēre pātreyalli saṁgraha māḍuvudu.",
      "devanagari": "ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಸ್ನಾನಾನಂತರಂ ಪುನರಾಚಮನೀಯಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು ದೇವರಿಗೆ ತೋರಿಸಿ ಅರ್ಘ್ಯ ಪಾತ್ರೆಯಲ್ಲಿ ನೀರನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು ಈಗ ಸಾಧಿಕೆ ಶರಣ್ಯೇ ತ್ರಯಂಬಕೆ ದೇವಿ ನಾರಾಯಣಿ ಹೇಳಿಕೊಂಡು ಅಭಿಷೇಕ ಮಾಡಬಹುದು ಸನ್ನಿಭಮಚ್ಚುತಾಂಕೆ ಸ್ವಾಸಿನ ಮಸ್ಯನು ನಿತ್ಯ ವಚ ಪ್ರವೃತ್ತಿಂ ಧ್ಯಾಯೇ ಗದಾ ಭಯಕರಂ ಸುಕೃತಾಂಜಲಿಂ ತಮ್ ಪ್ರಾಣಂ ಯಥೇಷ್ಟತನು ಮುನ್ನತ ಕರ್ಮ ಮಾಡಿದ ನೀರನ್ನು ಪ್ರತ್ಯೇಕ ಪಾತ್ರೆಯಲ್ಲಿ ಸಂಗ್ರಹ ಶೇಷ ಯಾರ ಪ್ರತಿಮೆ ಇದ್ದರೂ ಕೂಡ ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ನೀರಿನಿಂದ ಅವರಿಗೂ ಕೂಡ ಸ್ನಾನ ಮಾಡಿಸುವುದು ಆ ನೀರನ್ನು ಅರ್ಘ್ಯ ಪಾತ್ರೆಯಲ್ಲಿ ಮಾಡಿಕೊಳ್ಳುವುದು ಮುಖ್ಯ ಪ್ರಾಣನ ತೀರ್ಥವನ್ನು ಬೇರೆ ಪಾತ್ರೆಯಲ್ಲಿ ಸಂಗ್ರಹ ಮಾಡುವುದು ಇದಾದ",
      "meaning": "Complete source-audio coverage for abhiṣēka for lakṣmī and the attendant deities.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಸ್ನಾನಾನಂತರಂ ಪುನರಾಚಮನೀಯಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು ದೇವರಿಗೆ ತೋರಿಸಿ ಅರ್ಘ್ಯಪಾತ್ರೆಯಲ್ಲಿ ನೀರನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು. ಈಗ ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ತೀರ್ಥದಿಂದ ಲಕ್ಷ್ಮಿಗೂ ಕೂಡ ಅಭಿಷೇಕ ಮಾಡುವುದು. ಸರ್ವಮಂಗಲ ಮಾಂಗಲ್ಯೇ ಶಿವೇ ಸರ್ವಾರ್ಥಸಾಧಿಕೇ ಶರಣ್ಯೇ ತ್ರ್ಯಂಬಕೇ ದೇವಿ ನಾರಾಯಣಿ ನಮೋಸ್ತುತೇ. ನಂತರ ಹನುಮಂತನಿಗೆ ಅಭಿಷೇಕ. ಹನುಮಂತನ ಯಾವುದಾದರೂ ಸ್ತೋತ್ರವನ್ನು ಕೂಡ ಹೇಳಿಕೊಂಡು ಅಭಿಷೇಕ ಮಾಡಬಹುದು. ಓಂ ಉದ್ಯದ್ರವಿ ಪ್ರಕರಸನ್ನಿಭಮಚ್ಯುತಾಂಕೇ ಸ್ವಾಸೀನಮಸ್ಯನುತಿನಿತ್ಯವಚಃ ಪ್ರವೃತ್ತಿಂ ಜ್ಞಾಯೇದ್ಗದಾ ಭಯಕರಂ ಸಕೃತಾಂಜಲಿಂ ತಂ ಪ್ರಾಣಂ ಯಥೇಷ್ಟತನುಮುನ್ನತಕರ್ಮಶಕ್ತಿಂ. ಮುಖ್ಯ ಪ್ರಾಣನಿಗೆ, ಹನುಮಂತನಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ನೀರನ್ನು ಪ್ರತ್ಯೇಕ ಪಾತ್ರೆಯಲ್ಲಿ ಸಂಗ್ರಹ ಮಾಡುವುದು. ಹಾಗೆ ಗರುಡ, ಶೇಷ, ಯಾರ ಪ್ರತಿಮೆ ಇದ್ದರೂ ಕೂಡ ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ನೀರಿನಿಂದ. ಅವರು ಕೂಡ ಸ್ನಾನ ಮಾಡಿಸುವುದು, ಆ ನೀರನ್ನು ಅರ್ಘ್ಯಪಾತ್ರೆಯಲ್ಲಿ ಸಂಗ್ರಹ ಮಾಡಿಕೊಳ್ಳುವುದು. ಮುಖ್ಯ ಪ್ರಾಣನ ತೀರ್ಥವನ್ನು ಬೇರೆ ಪಾತ್ರೆಯಲ್ಲಿ ಸಂಗ್ರಹ ಮಾಡುವುದು. ",
      "captionOriginal": "ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಸ್ನಾನಾನಂತರಂ ಪುನರಾಚಮನೀಯಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು ದೇವರಿಗೆ ತೋರಿಸಿ ಅರ್ಘ್ಯ ಪಾತ್ರೆಯಲ್ಲಿ ನೀರನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು ಈಗ ಸಾಧಿಕೆ ಶರಣ್ಯೇ ತ್ರಯಂಬಕೆ ದೇವಿ ನಾರಾಯಣಿ ಹೇಳಿಕೊಂಡು ಅಭಿಷೇಕ ಮಾಡಬಹುದು ಸನ್ನಿಭಮಚ್ಚುತಾಂಕೆ ಸ್ವಾಸಿನ ಮಸ್ಯನು ನಿತ್ಯ ವಚ ಪ್ರವೃತ್ತಿಂ ಧ್ಯಾಯೇ ಗದಾ ಭಯಕರಂ ಸುಕೃತಾಂಜಲಿಂ ತಮ್ ಪ್ರಾಣಂ ಯಥೇಷ್ಟತನು ಮುನ್ನತ ಕರ್ಮ ಮಾಡಿದ ನೀರನ್ನು ಪ್ರತ್ಯೇಕ ಪಾತ್ರೆಯಲ್ಲಿ ಸಂಗ್ರಹ ಶೇಷ ಯಾರ ಪ್ರತಿಮೆ ಇದ್ದರೂ ಕೂಡ ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ನೀರಿನಿಂದ ಅವರಿಗೂ ಕೂಡ ಸ್ನಾನ ಮಾಡಿಸುವುದು ಆ ನೀರನ್ನು ಅರ್ಘ್ಯ ಪಾತ್ರೆಯಲ್ಲಿ ಮಾಡಿಕೊಳ್ಳುವುದು ಮುಖ್ಯ ಪ್ರಾಣನ ತೀರ್ಥವನ್ನು ಬೇರೆ ಪಾತ್ರೆಯಲ್ಲಿ ಸಂಗ್ರಹ ಮಾಡುವುದು ಇದಾದ",
      "losslessRoman": "ōṁ ōṁ namō nārāyaṇāya ōṁ śrīlakṣmī nārāyaṇāya snānānaṁtaraṁ punarācamanīyaṁ samarpayāmi eṁdu dēvarige tōrisi arghyapātreyalli nīrannu samarpaṇe māḍuvudu. īga dēvarige abhiṣēka māḍida tīrthadiṁda lakṣmigū kūḍa abhiṣēka māḍuvudu. sarvamaṁgala māṁgalyē śivē sarvārthasādhikē śaraṇyē tryaṁbakē dēvi nārāyaṇi namōstutē. naṁtara hanumaṁtanige abhiṣēka. hanumaṁtana yāvudādarū stōtravannu kūḍa hēḷikoṁḍu abhiṣēka māḍabahudu. ōṁ udyadravi prakarasannibhamacyutāṁkē svāsīnamasyanutinityavacaḥ pravr̥ttiṁ jñāyēdgadā bhayakaraṁ sakr̥tāṁjaliṁ taṁ prāṇaṁ yathēṣṭatanumunnatakarmaśaktiṁ. mukhya prāṇanige, hanumaṁtanige abhiṣēka māḍida nīrannu pratyēka pātreyalli saṁgraha māḍuvudu. hāge garuḍa, śēṣa, yāra pratime iddarū kūḍa dēvarige abhiṣēka māḍida nīriniṁda. avaru kūḍa snāna māḍisuvudu, ā nīrannu arghyapātreyalli saṁgraha māḍikoḷḷuvudu. mukhya prāṇana tīrthavannu bēre pātreyalli saṁgraha māḍuvudu.",
