      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "idāda naṁtara dēvarige vastra samarpaṇe. taṁ yajñaṁ br̥hiṣi praukṣan puruṣaṁ jātamagrataḥ, tēna dēvā ayajaṁta sādhyā r̥ṣayaśca yē. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmīnārāyaṇāya vastrayugmaṁ samarpayāmi. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmīnārāyaṇāya vastrānaṁtaraṁ punarācamanīyaṁ samarpayāmi. pratime kelavaru hēḷtāre, baṭṭeyiṁda sāligrāmavannu pratimeyannu varasikoḷḷuvudu aṁta hēḷtāre. kelavaru hēḷtāre sāligrāmana varasabāradu, pratimeyannu mātra varasabēku aṁta. nimma nimma paraṁpare hēgide ā paraṁpareyannu anusarisi. bēre yāva goṁdalakkū kūḍa oḷagāgabēḍi. pratimeyannu varasikoḷḷabēku aṁtaṁdre pratimeyannu varesi, hiṁde hēḷidaṁte pratyēkavāda vastra, mīsalu vastra dēvarige irali. nīvu upayōgisida vastravannu dēvarige upayōgisabēḍi.",
      "devanagari": "ನಂತರ ದೇವರಿಗೆ ವಸ್ತ್ರ ಸಮರ್ಪಣೆ ತೈ ಯಜ್ಞಂ ಬರಿಹಿಷಿ ಪ್ರೋಕ್ಷನ್ ಪುರುಷನ್ ಜಾತಮಗ್ರತಃ ತೇನ ದೇವ ಅಯಜಂತ ಸಾಧ್ಯ ಋಷಿಯಶ್ಚಯೇ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ನಾರಾಯಣಾಯ ವಸ್ತ್ರ ಯುಗ್ಮಂ ಸಮರ್ಪಯಾಮಿ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ವಸ್ತ್ರಾನಂತರಂ ಪುನರಾಚಮನೀಯಂ ಬಟ್ಟೆಯಿಂದ ಸಾಲಿಗ್ರಾಮವನ್ನು ಪ್ರತಿಮೆಯನ್ನು ವರೆಸಿಕೊಳ್ಳುವುದು ಅಂತ ಹೇಳ್ತಾರೆ ಕೆಲವರು ಹೇಳುತ್ತಾರೆ ಸಾಲಿಗ್ರಾಮನ ವರೆಸಬಾರದು ಪ್ರತಿಮೆಯನ್ನು ಮಾತ್ರ ವರೆಸಬೇಕು ಅಂತ ನಿಮ್ಮ ನಿಮ್ಮ ಪರಂಪರೆ ಹೇಗಿದೆ ಆ ಪರಂಪರೆಯನ್ನು ಅನುಸರಿಸಿ ಬೇರೆ ಯಾವ ಗೊಂದಲಕ್ಕೂ ಕೂಡ ಒಳಗಾಗಬೇಡಿ ಪ್ರತಿಮೆಯನ್ನು ಒರೆಸಿಕೊಳ್ಳಬೇಕು ಅಂತ ಅಂದ್ರೆ ಪ್ರತಿಮೆಯನ್ನು ಒರೆಸಿ ಹಿಂದೆ ಪ್ರತ್ಯೇಕವಾದ ವಸ್ತ್ರ ಮೀಸಲು ವಸ್ತ್ರ ದೇವರಿಗೆ ಇರಲಿ ನೀವು ಉಪಯೋಗಿಸಿದ ವಸ್ತ್ರವನ್ನು ದೇವರಿಗೆ",
      "meaning": "Complete source-audio coverage for vastra.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ಇದಾದ ನಂತರ ದೇವರಿಗೆ ವಸ್ತ್ರ ಸಮರ್ಪಣೆ. ತಂ ಯಜ್ಞಂ ಬೃಹಿಷಿ ಪ್ರೌಕ್ಷನ್ ಪುರುಷಂ ಜಾತಮಗ್ರತಃ, ತೇನ ದೇವಾ ಅಯಜಂತ ಸಾಧ್ಯಾ ಋಷಯಶ್ಚ ಯೇ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಓಂ ಶ್ರೀಲಕ್ಷ್ಮೀನಾರಾಯಣಾಯ ವಸ್ತ್ರಯುಗ್ಮಂ ಸಮರ್ಪಯಾಮಿ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಓಂ ಶ್ರೀಲಕ್ಷ್ಮೀನಾರಾಯಣಾಯ ವಸ್ತ್ರಾನಂತರಂ ಪುನರಾಚಮನೀಯಂ ಸಮರ್ಪಯಾಮಿ. ಪ್ರತಿಮೆ ಕೆಲವರು ಹೇಳ್ತಾರೆ, ಬಟ್ಟೆಯಿಂದ ಸಾಲಿಗ್ರಾಮವನ್ನು ಪ್ರತಿಮೆಯನ್ನು ವರಸಿಕೊಳ್ಳುವುದು ಅಂತ ಹೇಳ್ತಾರೆ. ಕೆಲವರು ಹೇಳ್ತಾರೆ ಸಾಲಿಗ್ರಾಮನ ವರಸಬಾರದು, ಪ್ರತಿಮೆಯನ್ನು ಮಾತ್ರ ವರಸಬೇಕು ಅಂತ. ನಿಮ್ಮ ನಿಮ್ಮ ಪರಂಪರೆ ಹೇಗಿದೆ ಆ ಪರಂಪರೆಯನ್ನು ಅನುಸರಿಸಿ. ಬೇರೆ ಯಾವ ಗೊಂದಲಕ್ಕೂ ಕೂಡ ಒಳಗಾಗಬೇಡಿ. ಪ್ರತಿಮೆಯನ್ನು ವರಸಿಕೊಳ್ಳಬೇಕು ಅಂತಂದ್ರೆ ಪ್ರತಿಮೆಯನ್ನು ವರೆಸಿ, ಹಿಂದೆ ಹೇಳಿದಂತೆ ಪ್ರತ್ಯೇಕವಾದ ವಸ್ತ್ರ, ಮೀಸಲು ವಸ್ತ್ರ ದೇವರಿಗೆ ಇರಲಿ. ನೀವು ಉಪಯೋಗಿಸಿದ ವಸ್ತ್ರವನ್ನು ದೇವರಿಗೆ ಉಪಯೋಗಿಸಬೇಡಿ. ",
      "captionOriginal": "ನಂತರ ದೇವರಿಗೆ ವಸ್ತ್ರ ಸಮರ್ಪಣೆ ತೈ ಯಜ್ಞಂ ಬರಿಹಿಷಿ ಪ್ರೋಕ್ಷನ್ ಪುರುಷನ್ ಜಾತಮಗ್ರತಃ ತೇನ ದೇವ ಅಯಜಂತ ಸಾಧ್ಯ ಋಷಿಯಶ್ಚಯೇ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ನಾರಾಯಣಾಯ ವಸ್ತ್ರ ಯುಗ್ಮಂ ಸಮರ್ಪಯಾಮಿ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ವಸ್ತ್ರಾನಂತರಂ ಪುನರಾಚಮನೀಯಂ ಬಟ್ಟೆಯಿಂದ ಸಾಲಿಗ್ರಾಮವನ್ನು ಪ್ರತಿಮೆಯನ್ನು ವರೆಸಿಕೊಳ್ಳುವುದು ಅಂತ ಹೇಳ್ತಾರೆ ಕೆಲವರು ಹೇಳುತ್ತಾರೆ ಸಾಲಿಗ್ರಾಮನ ವರೆಸಬಾರದು ಪ್ರತಿಮೆಯನ್ನು ಮಾತ್ರ ವರೆಸಬೇಕು ಅಂತ ನಿಮ್ಮ ನಿಮ್ಮ ಪರಂಪರೆ ಹೇಗಿದೆ ಆ ಪರಂಪರೆಯನ್ನು ಅನುಸರಿಸಿ ಬೇರೆ ಯಾವ ಗೊಂದಲಕ್ಕೂ ಕೂಡ ಒಳಗಾಗಬೇಡಿ ಪ್ರತಿಮೆಯನ್ನು ಒರೆಸಿಕೊಳ್ಳಬೇಕು ಅಂತ ಅಂದ್ರೆ ಪ್ರತಿಮೆಯನ್ನು ಒರೆಸಿ ಹಿಂದೆ ಪ್ರತ್ಯೇಕವಾದ ವಸ್ತ್ರ ಮೀಸಲು ವಸ್ತ್ರ ದೇವರಿಗೆ ಇರಲಿ ನೀವು ಉಪಯೋಗಿಸಿದ ವಸ್ತ್ರವನ್ನು ದೇವರಿಗೆ",
      "losslessRoman": "idāda naṁtara dēvarige vastra samarpaṇe. taṁ yajñaṁ br̥hiṣi praukṣan puruṣaṁ jātamagrataḥ, tēna dēvā ayajaṁta sādhyā r̥ṣayaśca yē. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmīnārāyaṇāya vastrayugmaṁ samarpayāmi. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmīnārāyaṇāya vastrānaṁtaraṁ punarācamanīyaṁ samarpayāmi. pratime kelavaru hēḷtāre, baṭṭeyiṁda sāligrāmavannu pratimeyannu varasikoḷḷuvudu aṁta hēḷtāre. kelavaru hēḷtāre sāligrāmana varasabāradu, pratimeyannu mātra varasabēku aṁta. nimma nimma paraṁpare hēgide ā paraṁpareyannu anusarisi. bēre yāva goṁdalakkū kūḍa oḷagāgabēḍi. pratimeyannu varasikoḷḷabēku aṁtaṁdre pratimeyannu varesi, hiṁde hēḷidaṁte pratyēkavāda vastra, mīsalu vastra dēvarige irali. nīvu upayōgisida vastravannu dēvarige upayōgisabēḍi.",
