      "devanagari": "ಪಶುಂತಾಂ ಚಕ್ರೆ ವಾಯವ್ಯಾನ್ ಆರಣ್ಯ ಗ್ರಾಮ್ಯಾಶ್ಚಯೇ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಯಜ್ಞೋಪವಿತಂ ಸಮರ್ಪಯಾಮಿ ಓಂ ತಸ್ಮಾತ್ ಯಜ್ಞಾತ್ ಸರ್ವಹುತ",
