      "mantra": "ōṁ tasmād yajñāt sarvahuta r̥caḥ sāmāni jajñirē, chaṁdāṁsi jajñirē tasmāt yajustasmādajāyata. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmīnārāyaṇāya gaṁdhaṁ samarpayāmi. gaṁdhavanna samarpaṇe māḍuvudu dēvarige. gaṁdhavanna modalē tēdu siddhapaḍisiṭṭukoṁḍirabēku. illa gaṁdhavannū tailakke avakāśavilladiddalli nīrannē śaṁkhadiṁda dēvarige gaṁdhada badalāgi arpaṇe māḍuvudu. dēvaru gīteyalli hēḷidāne, patraṁ puṣpaṁ phalaṁ tōyaṁ yō mē bhaktyā prayacchati, tadahaṁ bhaktyupahr̥taṁ aśnāmi prayatātmanaḥ. hāgāgi nīrannāgali, haṇṇannāgali, eleyannāgali yāvudannādrū kūḍa bhaktiyiṁda arpaṇe māḍidalli nānu svīkāra māḍtēne aṁta. hūvannāgali. ādare ella vidhavāda anukūlaviddalli, dravyada anukūlaviddalli, kālada anukūlavū iddalli, samayāvakāśaviddalli sōmāritanavillade iṣṭannū kūḍa hoṁdisikoṁḍu pūje māḍabēku. nānu illi ī saṁkṣipta pūjeyannu nānu tōristā irōdu anukūla illadiddavarige. gaṁdhada badalu śaṁkhadiṁda nīranna arpaṇe māḍuvudu.",
      "devanagari": "ರುಚಸಾಮಾನಿ ಜಗಜ್ಞಿರೆ ಛಂದಾಂಸಿಗ್ನಿರೇ ತಸ್ಮಾತ್ ಯಜು ತಸ್ಮಾದ ಜಾಯತ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಗಂಧಮ್ ಸಮರ್ಪಯಾಮಿ ಗಂಧವನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು ದೇವರಿಗೆ ಗಂಧವನ್ನು ಮೊದಲೇ ತೇದು ಸಿದ್ಧಪಡಿಸಿ ಇಟ್ಟುಕೊಂಡಿರಬೇಕು ಇಲ್ಲ ಗಂಧವನ್ನು ತೆಯಲಿಕ್ಕೆ ಅವಕಾಶವಿಲ್ಲದಿದ್ದಲ್ಲಿ ನೀರನ್ನೇ ಶಂಖದಿಂದ ದೇವರಿಗೆ ಗಂಧದ ಬದಲಾಗಿ ಅರ್ಪಣೆ ಮಾಡುವುದು ದೇವರು ಗೀತೆಯಲ್ಲಿ ಹೇಳಿದ್ದಾನೆ ಪತ್ರಂ ಪುಷ್ಪಂ ಫಲಂ ತೋಯಂ ಯೋಮೇ ಭಕ್ತ್ಯ ಪ್ರಯಚ್ಚತಿ ತದಹಂ ಭಕ್ತಿಪಹೃತಂ ಅಶ್ನಾಮಿ ಪ್ರಯತಾತ್ಮನಹ ಹಾಗಾಗಿ ನೀರನ್ನಾಗಲಿ ಎಲೆಯನ್ನಾಗಲಿ ಯಾವುದನ್ನಾದರೂ ಕೂಡ ಭಕ್ತಿಯಿಂದ ಅರ್ಪಣೆ ಮಾಡಿದಲ್ಲಿ ನಾನು ಸ್ವೀಕಾರ ಮಾಡುತ್ತೇನೆ ಹೂವನ್ನಾಗಲಿ ಆದರೆ ಎಲ್ಲಾ ವಿಧವಾದ ಅನುಕೂಲವಿದ್ದಲ್ಲಿ ದ್ರವ್ಯದ ಅನುಕೂಲವಿದ್ದಲ್ಲಿ ಕಾಲದ ಅನುಕೂಲವು ಇದ್ದಲ್ಲಿ ಸಮಯಾವಕಾಶವಿದ್ದಲ್ಲಿ ಸೋಮಾರಿ ತನವಿಲ್ಲದೆ ಇಷ್ಟನ್ನು ಕೂಡ ಹೊಂದಿಸಿಕೊಂಡು ಪೂಜೆ ಮಾಡಬೇಕು ನಾನು ಇಲ್ಲಿ ಸಂಕ್ಷಿಪ್ತ ಪೂಜೆಯನ್ನು ನಾನು ತೋರಿಸ್ತಾ ಇರೋದು ಅನುಕೂಲ ಇಲ್ಲದಿದ್ದವರಿಗೆ ಗಂಧದ ಬದಲು ಶಂಖದಿಂದ ನೀರನ್ನು ಅರ್ಪಣೆ",
      "meaning": "Complete source-audio coverage for gandha.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ಓಂ ತಸ್ಮಾದ್ ಯಜ್ಞಾತ್ ಸರ್ವಹುತ ಋಚಃ ಸಾಮಾನಿ ಜಜ್ಞಿರೇ, ಛಂದಾಂಸಿ ಜಜ್ಞಿರೇ ತಸ್ಮಾತ್ ಯಜುಸ್ತಸ್ಮಾದಜಾಯತ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಓಂ ಶ್ರೀಲಕ್ಷ್ಮೀನಾರಾಯಣಾಯ ಗಂಧಂ ಸಮರ್ಪಯಾಮಿ. ಗಂಧವನ್ನ ಸಮರ್ಪಣೆ ಮಾಡುವುದು ದೇವರಿಗೆ. ಗಂಧವನ್ನ ಮೊದಲೇ ತೇದು ಸಿದ್ಧಪಡಿಸಿಟ್ಟುಕೊಂಡಿರಬೇಕು. ಇಲ್ಲ ಗಂಧವನ್ನೂ ತೈಲಕ್ಕೆ ಅವಕಾಶವಿಲ್ಲದಿದ್ದಲ್ಲಿ ನೀರನ್ನೇ ಶಂಖದಿಂದ ದೇವರಿಗೆ ಗಂಧದ ಬದಲಾಗಿ ಅರ್ಪಣೆ ಮಾಡುವುದು. ದೇವರು ಗೀತೆಯಲ್ಲಿ ಹೇಳಿದಾನೆ, ಪತ್ರಂ ಪುಷ್ಪಂ ಫಲಂ ತೋಯಂ ಯೋ ಮೇ ಭಕ್ತ್ಯಾ ಪ್ರಯಚ್ಛತಿ, ತದಹಂ ಭಕ್ತ್ಯುಪಹೃತಂ ಅಶ್ನಾಮಿ ಪ್ರಯತಾತ್ಮನಃ. ಹಾಗಾಗಿ ನೀರನ್ನಾಗಲಿ, ಹಣ್ಣನ್ನಾಗಲಿ, ಎಲೆಯನ್ನಾಗಲಿ ಯಾವುದನ್ನಾದ್ರೂ ಕೂಡ ಭಕ್ತಿಯಿಂದ ಅರ್ಪಣೆ ಮಾಡಿದಲ್ಲಿ ನಾನು ಸ್ವೀಕಾರ ಮಾಡ್ತೇನೆ ಅಂತ. ಹೂವನ್ನಾಗಲಿ. ಆದರೆ ಎಲ್ಲ ವಿಧವಾದ ಅನುಕೂಲವಿದ್ದಲ್ಲಿ, ದ್ರವ್ಯದ ಅನುಕೂಲವಿದ್ದಲ್ಲಿ, ಕಾಲದ ಅನುಕೂಲವೂ ಇದ್ದಲ್ಲಿ, ಸಮಯಾವಕಾಶವಿದ್ದಲ್ಲಿ ಸೋಮಾರಿತನವಿಲ್ಲದೆ ಇಷ್ಟನ್ನೂ ಕೂಡ ಹೊಂದಿಸಿಕೊಂಡು ಪೂಜೆ ಮಾಡಬೇಕು. ನಾನು ಇಲ್ಲಿ ಈ ಸಂಕ್ಷಿಪ್ತ ಪೂಜೆಯನ್ನು ನಾನು ತೋರಿಸ್ತಾ ಇರೋದು ಅನುಕೂಲ ಇಲ್ಲದಿದ್ದವರಿಗೆ. ಗಂಧದ ಬದಲು ಶಂಖದಿಂದ ನೀರನ್ನ ಅರ್ಪಣೆ ಮಾಡುವುದು. ",
      "captionOriginal": "ರುಚಸಾಮಾನಿ ಜಗಜ್ಞಿರೆ ಛಂದಾಂಸಿಗ್ನಿರೇ ತಸ್ಮಾತ್ ಯಜು ತಸ್ಮಾದ ಜಾಯತ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಗಂಧಮ್ ಸಮರ್ಪಯಾಮಿ ಗಂಧವನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು ದೇವರಿಗೆ ಗಂಧವನ್ನು ಮೊದಲೇ ತೇದು ಸಿದ್ಧಪಡಿಸಿ ಇಟ್ಟುಕೊಂಡಿರಬೇಕು ಇಲ್ಲ ಗಂಧವನ್ನು ತೆಯಲಿಕ್ಕೆ ಅವಕಾಶವಿಲ್ಲದಿದ್ದಲ್ಲಿ ನೀರನ್ನೇ ಶಂಖದಿಂದ ದೇವರಿಗೆ ಗಂಧದ ಬದಲಾಗಿ ಅರ್ಪಣೆ ಮಾಡುವುದು ದೇವರು ಗೀತೆಯಲ್ಲಿ ಹೇಳಿದ್ದಾನೆ ಪತ್ರಂ ಪುಷ್ಪಂ ಫಲಂ ತೋಯಂ ಯೋಮೇ ಭಕ್ತ್ಯ ಪ್ರಯಚ್ಚತಿ ತದಹಂ ಭಕ್ತಿಪಹೃತಂ ಅಶ್ನಾಮಿ ಪ್ರಯತಾತ್ಮನಹ ಹಾಗಾಗಿ ನೀರನ್ನಾಗಲಿ ಎಲೆಯನ್ನಾಗಲಿ ಯಾವುದನ್ನಾದರೂ ಕೂಡ ಭಕ್ತಿಯಿಂದ ಅರ್ಪಣೆ ಮಾಡಿದಲ್ಲಿ ನಾನು ಸ್ವೀಕಾರ ಮಾಡುತ್ತೇನೆ ಹೂವನ್ನಾಗಲಿ ಆದರೆ ಎಲ್ಲಾ ವಿಧವಾದ ಅನುಕೂಲವಿದ್ದಲ್ಲಿ ದ್ರವ್ಯದ ಅನುಕೂಲವಿದ್ದಲ್ಲಿ ಕಾಲದ ಅನುಕೂಲವು ಇದ್ದಲ್ಲಿ ಸಮಯಾವಕಾಶವಿದ್ದಲ್ಲಿ ಸೋಮಾರಿ ತನವಿಲ್ಲದೆ ಇಷ್ಟನ್ನು ಕೂಡ ಹೊಂದಿಸಿಕೊಂಡು ಪೂಜೆ ಮಾಡಬೇಕು ನಾನು ಇಲ್ಲಿ ಸಂಕ್ಷಿಪ್ತ ಪೂಜೆಯನ್ನು ನಾನು ತೋರಿಸ್ತಾ ಇರೋದು ಅನುಕೂಲ ಇಲ್ಲದಿದ್ದವರಿಗೆ ಗಂಧದ ಬದಲು ಶಂಖದಿಂದ ನೀರನ್ನು ಅರ್ಪಣೆ",
