          "sourceRoman": "ādare ella vidhavāda anukūlaviddalli, dravyada anukūlaviddalli, kālada anukūlavū iddalli, samayāvakāśaviddalli sōmāritanavillade iṣṭannū kūḍa hoṁdisikoṁḍu pūje māḍabēku.",
