      "startSeconds": 366.32,
      "endSeconds": 409.08,
      "title": "Dhūpa",
      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "naṁtara dhūpa. keṁḍakke dhūpada puḍiyannu hāki dēvarige arpaṇe māḍuvudu. īga ellara maneyalli gyās irutte āddariṁdāgi keṁḍada anukūlavirōdilla, āddariṁdāgi śaṁkhadiṁda dhūpavannu samarpaṇe māḍuvudu; illa dhūpada puḍiyē idē barutte, ūdu batti aṁte, adannē dēvarige arpaṇe māḍuvudu. ōṁ yatpuruṣaṁ vyadadhuḥ katidhā vyakalpayan, mukhaṁ kimasya kau bāhū, kāvūrū pādāvucyētē. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmī nārāyaṇāya dhūpaṁ samarpayāmi.",
      "devanagari": "ಧೂಪದ ಪುಡಿಯನ್ನು ಹಾಕಿ ದೇವರಿಗೆ ಅರ್ಪಣೆ ಮಾಡುವುದು ಈಗ ಎಲ್ಲರ ಮನೆಯಲ್ಲಿ ಗ್ಯಾಸ್ ಇರುತ್ತೆ ಆದ್ದರಿಂದಾಗಿ ಕೆಂಡದ ಅನುಕೂಲವಿರುವುದಿಲ್ಲ ಆದ್ದರಿಂದಾಗಿ ಶಂಖದಿಂದ ಧೂಪವನ್ನು ಸಮರ್ಪಣೆ ಮಾಡಬಹುದು ಇಲ್ಲ ಧೂಪದ ಪುಡಿ ಇದೆ ಬರುತ್ತೆ ಊದು ಬತ್ತಿಯಂತೆ ಅದನ್ನೇ ದೇವರಿಗೆ ಅರ್ಪಣೆ ಮಾಡುವುದು ಓಂ ಯತ್ಪುರುಷಂ ವ್ಯದಹು ಕತಿಧಾವ್ಯ ಕಲ್ಪಯನ್ ಮುಖಂ ಕಿಮಸ್ಯ ಕೌ ಬಾಹು ಕಾವು ರೂಪಾದ ಉಚ್ಚೇತೆ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ",
      "meaning": "Complete source-audio coverage for dhūpa.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ನಂತರ ಧೂಪ. ಕೆಂಡಕ್ಕೆ ಧೂಪದ ಪುಡಿಯನ್ನು ಹಾಕಿ ದೇವರಿಗೆ ಅರ್ಪಣೆ ಮಾಡುವುದು. ಈಗ ಎಲ್ಲರ ಮನೆಯಲ್ಲಿ ಗ್ಯಾಸ್ ಇರುತ್ತೆ ಆದ್ದರಿಂದಾಗಿ ಕೆಂಡದ ಅನುಕೂಲವಿರೋದಿಲ್ಲ, ಆದ್ದರಿಂದಾಗಿ ಶಂಖದಿಂದ ಧೂಪವನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು; ಇಲ್ಲ ಧೂಪದ ಪುಡಿಯೇ ಇದೇ ಬರುತ್ತೆ, ಊದು ಬತ್ತಿ ಅಂತೆ, ಅದನ್ನೇ ದೇವರಿಗೆ ಅರ್ಪಣೆ ಮಾಡುವುದು. ॐ ಯತ್ಪುರುಷಂ ವ್ಯದಧುಃ ಕತಿಧಾ ವ್ಯಕಲ್ಪಯನ್, ಮುಖಂ ಕಿಮಸ್ಯ ಕೌ ಬಾಹೂ, ಕಾವೂರೂ ಪಾದಾವುಚ್ಯೇತೇ. ॐ ॐ ನಮೋ ನಾರಾಯಣಾಯ, ॐ ಶ್ರೀಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಧೂಪಂ ಸಮರ್ಪಯಾಮಿ. ",
      "captionOriginal": "ಧೂಪದ ಪುಡಿಯನ್ನು ಹಾಕಿ ದೇವರಿಗೆ ಅರ್ಪಣೆ ಮಾಡುವುದು ಈಗ ಎಲ್ಲರ ಮನೆಯಲ್ಲಿ ಗ್ಯಾಸ್ ಇರುತ್ತೆ ಆದ್ದರಿಂದಾಗಿ ಕೆಂಡದ ಅನುಕೂಲವಿರುವುದಿಲ್ಲ ಆದ್ದರಿಂದಾಗಿ ಶಂಖದಿಂದ ಧೂಪವನ್ನು ಸಮರ್ಪಣೆ ಮಾಡಬಹುದು ಇಲ್ಲ ಧೂಪದ ಪುಡಿ ಇದೆ ಬರುತ್ತೆ ಊದು ಬತ್ತಿಯಂತೆ ಅದನ್ನೇ ದೇವರಿಗೆ ಅರ್ಪಣೆ ಮಾಡುವುದು ಓಂ ಯತ್ಪುರುಷಂ ವ್ಯದಹು ಕತಿಧಾವ್ಯ ಕಲ್ಪಯನ್ ಮುಖಂ ಕಿಮಸ್ಯ ಕೌ ಬಾಹು ಕಾವು ರೂಪಾದ ಉಚ್ಚೇತೆ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ",
      "losslessRoman": "naṁtara dhūpa. keṁḍakke dhūpada puḍiyannu hāki dēvarige arpaṇe māḍuvudu. īga ellara maneyalli gyās irutte āddariṁdāgi keṁḍada anukūlavirōdilla, āddariṁdāgi śaṁkhadiṁda dhūpavannu samarpaṇe māḍuvudu; illa dhūpada puḍiyē idē barutte, ūdu batti aṁte, adannē dēvarige arpaṇe māḍuvudu. ōṁ yatpuruṣaṁ vyadadhuḥ katidhā vyakalpayan, mukhaṁ kimasya kau bāhū, kāvūrū pādāvucyētē. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmī nārāyaṇāya dhūpaṁ samarpayāmi.",
