      "originalScript": "ಆಮೇಲೆ ಐದು ಬಾರಿ ನೀರನ್ನು ಬಿಡೋದು. ಓಂ ಪ್ರಾಣಾಯ ಸ್ವಾಹಾ, ಓಂ ಅಪಾನಾಯ ಸ್ವಾಹಾ, ಓಂ ಉದಾನಾಯ ಸ್ವಾಹಾ, ಓಂ ವ್ಯಾನಾಯ ಸ್ವಾಹಾ, ಓಂ ಸಮಾನಾಯ ಸ್ವಾಹಾ, ಓಂ ಬ್ರಹ್ಮಣೇ ಸ್ವಾಹಾ ಎಂದು. ದೇವರು ಹತ್ತು ಬಾರಿ ನಾರಾಯಣ ಅಷ್ಟಾಕ್ಷರ ಮಂತ್ರವನ್ನು ಜಪ ಮಾಡುವುದು. ದೇವರು ತನ್ನ ಮಂಗಳ ದೃಷ್ಟಿಯನ್ನು ಆಹಾರದ ಮೇಲೆ ಬೀರಿ, ಇದರಲ್ಲಿರೋ ವಿಷವನ್ನೆಲ್ಲಾ ಪರಿಹಾರ ಮಾಡಿ, ಇದರಲ್ಲಿರೋ ಸಾರಭಾಗವನ್ನು ತಾನು ಸ್ವೀಕಾರ ಮಾಡಿ, ನಾವು ತಿಂದ್ಲಿಕ್ಕೆ ಯೋಗ್ಯವನ್ನಾಗಿ ಮಾಡ್ತಾ ಇದ್ದಾನೆ ಎಂದು ಭಾವಿಸಿಕೊಳ್ಳಬೇಕು. ಓಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಓಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಓಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಓಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಓಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಓಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಓಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಓಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಓಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಓಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಚಂದ್ರಮಾ ಮನಸೋ ಜಾತಃ, ಚಕ್ಷೋಃ ಸೂರ್ಯೋ ಅಜಾಯತ, ಮುಖಾದಿಂದ್ರಶ್ಚಾಗ್ನಿಶ್ಚ, ಪ್ರಾಣಾದ್ವಾಯುರಜಾಯತ. ಓಂ, ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಯವಂ. ಶ್ರೀ ಲಕ್ಷ್ಮೀನಾರಾಯಣಾಯ ಪುರತಃ ಸ್ಥಾಪಿತ ಫಲಂ ಜಲಂಚ ನಿವೇದಯಾಮಿ ಎಂದು ಪ್ರಾರ್ಥನೆ ಮಾಡಿ. ಅಮೃತಾಪಿಧಾನಮಸಿ ಸ್ವಾಹಾ ಮಹಾ ನೈವೇದ್ಯಂ ವಿಸರ್ಜಯಾಮಿ ಎಂದು ಮತ್ತೆ ಶಂಖದಿಂದ ನೀರನ್ನು ಅರ್ಘ್ಯ ಪಾತ್ರೆಗೆ ಬಿಡುವುದು. ",
