      "losslessRoman": "āmēle aidu bāri nīrannu biḍōdu. ōṁ prāṇāya svāhā, ōṁ apānāya svāhā, ōṁ udānāya svāhā, ōṁ vyānāya svāhā, ōṁ samānāya svāhā, ōṁ brahmaṇē svāhā eṁdu. dēvaru hattu bāri nārāyaṇa aṣṭākṣara maṁtravannu japa māḍuvudu. dēvaru tanna maṁgaḷa dr̥ṣṭiyannu āhārada mēle bīri, idarallirō viṣavannellā parihāra māḍi, idarallirō sārabhāgavannu tānu svīkāra māḍi, nāvu tiṁdlikke yōgyavannāgi māḍtā iddāne eṁdu bhāvisikoḷḷabēku. ōṁ, ōṁ namō nārāyaṇāya yavaṁ. ōṁ, ōṁ namō nārāyaṇāya yavaṁ. ōṁ, ōṁ namō nārāyaṇāya yavaṁ. ōṁ, ōṁ namō nārāyaṇāya yavaṁ. ōṁ, ōṁ namō nārāyaṇāya yavaṁ. ōṁ, ōṁ namō nārāyaṇāya yavaṁ. ōṁ, ōṁ namō nārāyaṇāya yavaṁ. ōṁ, ōṁ namō nārāyaṇāya yavaṁ. ōṁ, ōṁ namō nārāyaṇāya yavaṁ. ōṁ, ōṁ namō nārāyaṇāya yavaṁ. caṁdramā manasō jātaḥ, cakṣōḥ sūryō ajāyata, mukhādiṁdraścāgniśca, prāṇādvāyurajāyata. ōṁ, ōṁ namō nārāyaṇāya yavaṁ. śrī lakṣmīnārāyaṇāya purataḥ sthāpita phalaṁ jalaṁca nivēdayāmi eṁdu prārthane māḍi. amr̥tāpidhānamasi svāhā mahā naivēdyaṁ visarjayāmi eṁdu matte śaṁkhadiṁda nīrannu arghya pātrege biḍuvudu.",
