      "originalScript": "ನಂತರ ಲಕ್ಷ್ಮೀ ದೇವಿಗೆ ತೀರ್ಥವನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು. ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ತೀರ್ಥವನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು. ಲಂ ಲಕ್ಷ್ಮೀ ನಮಃ ತೀರ್ಥಂ ನಿವೇದಯಾಮಿ, ಹಂ ಹನುಮತೇ ನಮಃ ತೀರ್ಥಂ ನಿವೇದಯಾಮಿ. ನಂತರ ರಮಾ ಬ್ರಹ್ಮಾದಯೋ ದೇವಾಃ ಸನಕಾದ್ಯಾಃ ಶುಕಾದಯಃ, ಶ್ರೀನೃಸಿಂಹ ಪ್ರಸಾದೋಽಯಂ ಸರ್ವೇ ಗೃಹ್ಣಂತು ವೈಷ್ಣವಾಃ ಎಂದು ದೇವರ ತೀರ್ಥವನ್ನ ನೈವೇದ್ಯದ ಮೇಲೆ ಹಾಕಬೇಕು. ದೇವರ ನೈವೇದ್ಯಾದ ನಂತರ ಮುಖ್ಯ ಪ್ರಾಣನಿಗೆ ನೈವೇದ್ಯವನ್ನು ಅರ್ಪಣೆ ಮಾಡುವುದು. ಈ ಶ್ಲೋಕವನ್ನು ಹೇಳುವುದು. ಲಕ್ಷ್ಮೀ ದೇವಿಯಿಂದ ಆರಂಭಿಸಿ ಎಲ್ಲ ದೇವತೆಗಳು ದೇವರ ನೈವೇದ್ಯವನ್ನು ಸ್ವೀಕಾರ ಮಾಡಲಿ ಅಂತ. ರಮಾ ಬ್ರಹ್ಮಾದಯೋ ದೇವಾಃ ಸನಕಾದ್ಯಾಃ ಶುಕಾದಯಃ, ಶ್ರೀನೃಸಿಂಹ ಪ್ರಸಾದೋಽಯಂ ಸರ್ವೇ ಗೃಹ್ಣಂತು ವೈಷ್ಣವಾಃ ಎಂದು ದೇವರ ತೀರ್ಥವನ್ನ ದೇವರ ನೈವೇದ್ಯದ ಮೇಲೆ ಹಾಕುವುದು. ಈಗ ನಂತರ ಮಂಗಳಾರತಿ.",
      "captionOriginal": "ಬಿಡುವುದು ನಂತರ ಮಾಡುವುದು ದೇವರಿಗೆ ಅಭಿಷೇಕ ಮಾಡಿದ ತೀರ್ಥವನ್ನು ಸಮರ್ಪಣೆ ಮಾಡುವುದು ಲಂ ಲಕ್ಷ್ಮಿ ನಮಃ ತೀರ್ಥಂ ನಿವೇದಯಾಮಿ ಹಂ ಹನುಮತೇ ನಮಃ ತೀರ್ಥಂ ನಿವೇದಯಾಮಿ ನಂತರ ರಮ ಬ್ರಹ್ಮದಯೋ ದೇವಾಹ ಸನಕಾದ್ಯ ಶುಕಾದಯಹ ಶ್ರೀ ನರಸಿಂಹ ಪ್ರಸಾದೋಯಂ ಸರ್ವೇ ಗೃಹಂತು ವೈಷ್ಣವಹ ತೀರ್ಥವನ್ನ ಆ ನೈವೇದ್ಯದ ಮೇಲೆ ಹಾಕಬೇಕು ದೇವರ ನೈವೇದ್ಯ ಆದ ನಂತರ ಮುಖ್ಯ ಪ್ರಾಣನಿಗೆ ನೈವೇದ್ಯವನ್ನು ಅರ್ಪಣೆ ಮಾಡುವುದು ಈ ಶ್ಲೋಕವನ್ನು ಹೇಳುವುದು ಲಕ್ಷ್ಮೀದೇವಿಯಿಂದ ಆರಂಭಿಸಿ ಎಲ್ಲ ದೇವತೆಗಳು ದೇವರ ನೈವೇದ್ಯವನ್ನು ಸ್ವೀಕಾರ ಮಾಡಲಿ ಅಂತ ರಮ ಬ್ರಹ್ಮದಯೋ ದೇವಾಹ ಸನಕಾದ್ಯ ಶುಕಾದಯಹ ಶ್ರೀ ನರಸಿಂಹ ಪ್ರಸಾದೋಯಂ ಸರ್ವೇ ಗ್ರಂಡಂತು ವೈಷ್ಣವಹ ಎಂದು ದೇವರ ತೀರ್ಥವನ್ನ ದೇವರ ನೈವೇದ್ಯದ ಮೇಲೆ ಹಾಕುವುದು ಈಗ ನಂತರ ಮಂಗಳಾರತಿ",
      "losslessRoman": "naṁtara lakṣmī dēvige tīrthavannu samarpaṇe māḍuvudu. dēvarige abhiṣēka māḍida tīrthavannu samarpaṇe māḍuvudu. laṁ lakṣmī namaḥ tīrthaṁ nivēdayāmi, haṁ hanumatē namaḥ tīrthaṁ nivēdayāmi. naṁtara ramā brahmādayō dēvāḥ sanakādyāḥ śukādayaḥ, śrīnr̥siṁha prasādō'yaṁ sarvē gr̥hṇaṁtu vaiṣṇavāḥ eṁdu dēvara tīrthavanna naivēdyada mēle hākabēku. dēvara naivēdyāda naṁtara mukhya prāṇanige naivēdyavannu arpaṇe māḍuvudu. ī ślōkavannu hēḷuvudu. lakṣmī dēviyiṁda āraṁbhisi ella dēvategaḷu dēvara naivēdyavannu svīkāra māḍali aṁta. ramā brahmādayō dēvāḥ sanakādyāḥ śukādayaḥ, śrīnr̥siṁha prasādō'yaṁ sarvē gr̥hṇaṁtu vaiṣṇavāḥ eṁdu dēvara tīrthavanna dēvara naivēdyada mēle hākuvudu. īga naṁtara maṁgaḷārati.",
