      "title": "Maṅgalārati",
      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "nimage priyavāda yāvudādarū dēvara stōtravanna hēḷi maṁgaḷārtiyannu beḷagabahudu. jayatyajō khaṁḍaguṇōrumaṁḍalaḥ sadōditō jñānamarīcimālī, svabhaktahārdōccatamō nihaṁtā vyāsāvatārō harirātmabhāskaraḥ. jayatyajō kṣīṇasukhātmabiṁbaḥ svaiśvaryakāṁti pratatassadōditaḥ, svabhaktasaṁtāpaduriṣṭahaṁtā rāmāvatārō harirīśacaṁdramāḥ. jayatyasaṁkhyōrubalāṁbupūrō guṇōccaratnākarātnavaibhavaḥ, sadā sadātmajñānadīdhirāpyaḥ kr̥ṣṇāvatārō harirēkasāgaraḥ. maṁgaḷārti māḍuva uddēśa nīrājana. dēvara rūpavannu kaṇtuṁba tuṁbikoḷḷōdu dīpada beḷakinalli. idariṁda dēvaralli bhakti jāsti āgatte. adakkāgi āratiyannu beḷaguvudu. dēvarige beḷagida āratiyannu nāvu kaṇṇige, hr̥dayakke muṭṭikoḷḷōdu. idariṁda hr̥dayadalliruva ajñānavella parihāravāgali ennuva prārthane ī maṁgaḷārti togoḷōdaralli ide.",
      "devanagari": "ನಿಮಗೆ ಪ್ರಿಯವಾದ ಯಾವುದಾದರೂ ದೇವರ ಸ್ತೋತ್ರವನ್ನು ಹೇಳಿ ಸದೋದಿತೋ ಜ್ಞಾನ ಮರೀಚಿಮಾಲಿ ಸ್ವಭಕ್ತ ಹಾರ್ದೋಚ್ಚತಮೋನಿಹಂತ ಜೋಕ್ಷಿಣ ಸುಖ ಆತ್ಮಬಿಂಬಹ ಸ್ವೈಶ್ವರ್ಯ ಕಾಂತಿ ಪ್ರತತ ಸದೋದಿತಹ ಸ್ವಭಕ್ತ ಸಂತಾಪ ದುರಿಷ್ಟ ಹಂತ ರಾಮಾವತಾರೋ ಹರಿರೀಶ ಚಂದ್ರಮಾಹ ಜಯತ್ಯ ಸಂಖ್ಯೋರು ಬಲಾಂಬು ಪೂರೋ ಗುಣೋಚ್ಚ ರತ್ನಾಕರಾತ್ಮ ವೈಭವಹ ಸದಾ ಸದಾತ್ಮಜ್ಞ ನದಿ ಭಿರಾಪ್ಯಹ ಕೃಷ್ಣಾವತಾರೋ ಹರಿರೇಖ ಮಂಗಳಾರತಿ ಮಾಡುವ ಉದ್ದೇಶ ನೀರಾಜನ ದೇವರ ರೂಪವನ್ನು ಕಣ್ುತುಂಬ ತುಂಬಿಕೊಳ್ಳುವುದು ಬೆಳಕಿನಲ್ಲಿ ಇದರಿಂದ ದೇವರಲ್ಲಿ ಭಕ್ತಿ ಜಾಸ್ತಿ ಆಗುತ್ತೆ ಅದಕ್ಕಾಗಿ ಆರತಿಯನ್ನು ಬೆಳಗುವುದು ದೇವರಿಗೆ ಬೆಳಗಿದ ಆರತಿಯನ್ನು ನಾವು ಕಣ್ಣಿಗೆ ಹೃದಯಕ್ಕೆ ಮುಟ್ಟಿಕೊಳ್ಳುವುದು ಇದರಿಂದ ಹೃದಯದಲ್ಲಿರುವ ಅಜ್ಞಾನವೆಲ್ಲ ಪರಿಹಾರವಾಗಲಿ ಎನ್ನುವ ಪ್ರಾರ್ಥನೆ ಈ ಮಂಗಳಾರತಿ",
      "meaning": "Complete source-audio coverage for maṅgalārati.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ನಿಮಗೆ ಪ್ರಿಯವಾದ ಯಾವುದಾದರೂ ದೇವರ ಸ್ತೋತ್ರವನ್ನ ಹೇಳಿ ಮಂಗಳಾರ್ತಿಯನ್ನು ಬೆಳಗಬಹುದು. ಜಯತ್ಯಜೋ ಖಂಡಗುಣೋರುಮಂಡಲಃ ಸದೋದಿತೋ ಜ್ಞಾನಮರೀಚಿಮಾಲೀ, ಸ್ವಭಕ್ತಹಾರ್ದೋಚ್ಚತಮೋ ನಿಹಂತಾ ವ್ಯಾಸಾವತಾರೋ ಹರಿರಾತ್ಮಭಾಸ್ಕರಃ. ಜಯತ್ಯಜೋ ಕ್ಷೀಣಸುಖಾತ್ಮಬಿಂಬಃ ಸ್ವೈಶ್ವರ್ಯಕಾಂತಿ ಪ್ರತತಸ್ಸದೋದಿತಃ, ಸ್ವಭಕ್ತಸಂತಾಪದುರಿಷ್ಟಹಂತಾ ರಾಮಾವತಾರೋ ಹರಿರೀಶಚಂದ್ರಮಾಃ. ಜಯತ್ಯಸಂಖ್ಯೋರುಬಲಾಂಬುಪೂರೋ ಗುಣೋಚ್ಚರತ್ನಾಕರಾತ್ನವೈಭವಃ, ಸದಾ ಸದಾತ್ಮಜ್ಞಾನದೀಧಿರಾಪ್ಯಃ ಕೃಷ್ಣಾವತಾರೋ ಹರಿರೇಕಸಾಗರಃ. ಮಂಗಳಾರ್ತಿ ಮಾಡುವ ಉದ್ದೇಶ ನೀರಾಜನ. ದೇವರ ರೂಪವನ್ನು ಕಣ್ತುಂಬ ತುಂಬಿಕೊಳ್ಳೋದು ದೀಪದ ಬೆಳಕಿನಲ್ಲಿ. ಇದರಿಂದ ದೇವರಲ್ಲಿ ಭಕ್ತಿ ಜಾಸ್ತಿ ಆಗತ್ತೆ. ಅದಕ್ಕಾಗಿ ಆರತಿಯನ್ನು ಬೆಳಗುವುದು. ದೇವರಿಗೆ ಬೆಳಗಿದ ಆರತಿಯನ್ನು ನಾವು ಕಣ್ಣಿಗೆ, ಹೃದಯಕ್ಕೆ ಮುಟ್ಟಿಕೊಳ್ಳೋದು. ಇದರಿಂದ ಹೃದಯದಲ್ಲಿರುವ ಅಜ್ಞಾನವೆಲ್ಲ ಪರಿಹಾರವಾಗಲಿ ಎನ್ನುವ ಪ್ರಾರ್ಥನೆ ಈ ಮಂಗಳಾರ್ತಿ ತೊಗೊಳೋದರಲ್ಲಿ ಇದೆ. ",
      "captionOriginal": "ನಿಮಗೆ ಪ್ರಿಯವಾದ ಯಾವುದಾದರೂ ದೇವರ ಸ್ತೋತ್ರವನ್ನು ಹೇಳಿ ಸದೋದಿತೋ ಜ್ಞಾನ ಮರೀಚಿಮಾಲಿ ಸ್ವಭಕ್ತ ಹಾರ್ದೋಚ್ಚತಮೋನಿಹಂತ ಜೋಕ್ಷಿಣ ಸುಖ ಆತ್ಮಬಿಂಬಹ ಸ್ವೈಶ್ವರ್ಯ ಕಾಂತಿ ಪ್ರತತ ಸದೋದಿತಹ ಸ್ವಭಕ್ತ ಸಂತಾಪ ದುರಿಷ್ಟ ಹಂತ ರಾಮಾವತಾರೋ ಹರಿರೀಶ ಚಂದ್ರಮಾಹ ಜಯತ್ಯ ಸಂಖ್ಯೋರು ಬಲಾಂಬು ಪೂರೋ ಗುಣೋಚ್ಚ ರತ್ನಾಕರಾತ್ಮ ವೈಭವಹ ಸದಾ ಸದಾತ್ಮಜ್ಞ ನದಿ ಭಿರಾಪ್ಯಹ ಕೃಷ್ಣಾವತಾರೋ ಹರಿರೇಖ ಮಂಗಳಾರತಿ ಮಾಡುವ ಉದ್ದೇಶ ನೀರಾಜನ ದೇವರ ರೂಪವನ್ನು ಕಣ್ುತುಂಬ ತುಂಬಿಕೊಳ್ಳುವುದು ಬೆಳಕಿನಲ್ಲಿ ಇದರಿಂದ ದೇವರಲ್ಲಿ ಭಕ್ತಿ ಜಾಸ್ತಿ ಆಗುತ್ತೆ ಅದಕ್ಕಾಗಿ ಆರತಿಯನ್ನು ಬೆಳಗುವುದು ದೇವರಿಗೆ ಬೆಳಗಿದ ಆರತಿಯನ್ನು ನಾವು ಕಣ್ಣಿಗೆ ಹೃದಯಕ್ಕೆ ಮುಟ್ಟಿಕೊಳ್ಳುವುದು ಇದರಿಂದ ಹೃದಯದಲ್ಲಿರುವ ಅಜ್ಞಾನವೆಲ್ಲ ಪರಿಹಾರವಾಗಲಿ ಎನ್ನುವ ಪ್ರಾರ್ಥನೆ ಈ ಮಂಗಳಾರತಿ",
      "losslessRoman": "nimage priyavāda yāvudādarū dēvara stōtravanna hēḷi maṁgaḷārtiyannu beḷagabahudu. jayatyajō khaṁḍaguṇōrumaṁḍalaḥ sadōditō jñānamarīcimālī, svabhaktahārdōccatamō nihaṁtā vyāsāvatārō harirātmabhāskaraḥ. jayatyajō kṣīṇasukhātmabiṁbaḥ svaiśvaryakāṁti pratatassadōditaḥ, svabhaktasaṁtāpaduriṣṭahaṁtā rāmāvatārō harirīśacaṁdramāḥ. jayatyasaṁkhyōrubalāṁbupūrō guṇōccaratnākarātnavaibhavaḥ, sadā sadātmajñānadīdhirāpyaḥ kr̥ṣṇāvatārō harirēkasāgaraḥ. maṁgaḷārti māḍuva uddēśa nīrājana. dēvara rūpavannu kaṇtuṁba tuṁbikoḷḷōdu dīpada beḷakinalli. idariṁda dēvaralli bhakti jāsti āgatte. adakkāgi āratiyannu beḷaguvudu. dēvarige beḷagida āratiyannu nāvu kaṇṇige, hr̥dayakke muṭṭikoḷḷōdu. idariṁda hr̥dayadalliruva ajñānavella parihāravāgali ennuva prārthane ī maṁgaḷārti togoḷōdaralli ide.",
