          "text": "jayatyajō khaṁḍaguṇōrumaṁḍalaḥ sadōditō jñānamarīcimālī, svabhaktahārdōccatamō nihaṁtā vyāsāvatārō harirātmabhāskaraḥ.\n\njayatyajō kṣīṇasukhātmabiṁbaḥ svaiśvaryakāṁti pratatassadōditaḥ, svabhaktasaṁtāpaduriṣṭahaṁtā rāmāvatārō harirīśacaṁdramāḥ.\n\njayatyasaṁkhyōrubalāṁbupūrō guṇōccaratnākarātnavaibhavaḥ, sadā sadātmajñānadīdhirāpyaḥ kr̥ṣṇāvatārō harirēkasāgaraḥ."
