      "title": "Namaskāra",
      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "naṁtara dēvarige namaskāra. avara maneyalli anukūlaviddalli dēvarige namaskāra māḍuvudu, horage baṁdu. nābhyā āsīt aṁtarikṣaṁ, śīrṣṇō dyauḥ samavartata, padbhyāṁ bhūmirdiśaḥ śrōtrāt tathā lōkān akalpayan. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmīnārāyaṇāya namaskāraṁ samarpayāmi eṁdu.",
      "devanagari": "ತಗೊಳ್ಳುವುದರಲ್ಲಿ ಇದೆ ನಂತರ ದೇವರಿಗೆ ನಮಸ್ಕಾರ ಅವರ ಮನೆಯ ಅನುಕೂಲವಿದ್ದಲ್ಲಿ ದೇವರಿಗೆ ನಮಸ್ಕಾರ ಮಾಡುವುದು ಹೊರಗೆ ಬಂದು ನಾಭ್ಯ ಆಸಿ ಅಂತರಿಕ್ಷಮ್ ಶೀರ್ಷಣೋದ್ಯೋ ಸಮವರ್ತತ ಪದ್ಭ್ಯಾಂ ಭೂಮಿರ್ದಿಶ್ರೋತ್ರ ತಥಾ ಲೋಕಾಂ ಅಕಲ್ಪಯನ್ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ನಮಸ್ಕಾರಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು ಪ್ರದಕ್ಷಿಣೆ",
      "meaning": "Complete source-audio coverage for namaskāra.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ನಂತರ ದೇವರಿಗೆ ನಮಸ್ಕಾರ. ಅವರ ಮನೆಯಲ್ಲಿ ಅನುಕೂಲವಿದ್ದಲ್ಲಿ ದೇವರಿಗೆ ನಮಸ್ಕಾರ ಮಾಡುವುದು, ಹೊರಗೆ ಬಂದು. ನಾಭ್ಯಾ ಆಸೀತ್ ಅಂತರಿಕ್ಷಂ, ಶೀರ್ಷ್ಣೋ ದ್ಯೌಃ ಸಮವರ್ತತ, ಪದ್ಭ್ಯಾಂ ಭೂಮಿರ್ದಿಶಃ ಶ್ರೋತ್ರಾತ್ ತಥಾ ಲೋಕಾನ್ ಅಕಲ್ಪಯನ್. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಓಂ ಶ್ರೀಲಕ್ಷ್ಮೀನಾರಾಯಣಾಯ ನಮಸ್ಕಾರಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು. ",
      "captionOriginal": "ತಗೊಳ್ಳುವುದರಲ್ಲಿ ಇದೆ ನಂತರ ದೇವರಿಗೆ ನಮಸ್ಕಾರ ಅವರ ಮನೆಯ ಅನುಕೂಲವಿದ್ದಲ್ಲಿ ದೇವರಿಗೆ ನಮಸ್ಕಾರ ಮಾಡುವುದು ಹೊರಗೆ ಬಂದು ನಾಭ್ಯ ಆಸಿ ಅಂತರಿಕ್ಷಮ್ ಶೀರ್ಷಣೋದ್ಯೋ ಸಮವರ್ತತ ಪದ್ಭ್ಯಾಂ ಭೂಮಿರ್ದಿಶ್ರೋತ್ರ ತಥಾ ಲೋಕಾಂ ಅಕಲ್ಪಯನ್ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ನಮಸ್ಕಾರಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು ಪ್ರದಕ್ಷಿಣೆ",
      "losslessRoman": "naṁtara dēvarige namaskāra. avara maneyalli anukūlaviddalli dēvarige namaskāra māḍuvudu, horage baṁdu. nābhyā āsīt aṁtarikṣaṁ, śīrṣṇō dyauḥ samavartata, padbhyāṁ bhūmirdiśaḥ śrōtrāt tathā lōkān akalpayan. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmīnārāyaṇāya namaskāraṁ samarpayāmi eṁdu.",
