      "mantra": "pradakṣiṇe baralikke avakāśaviddalli pradakṣiṇe baralikkū uṁṭu. saptāsyāsan paridhayaḥ, triḥ sapta samidhaḥ kr̥tāḥ. dēvā yadyajñaṁ tanvānā abadhnan puruṣaṁ paśuṁ eṁdu. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmī nārāyaṇāya, pradakṣiṇaṁ samarpayāmi eṁdu śaṁkhadalli oṁdu dēvarige tōrisi arghyapātreyalli nīrannu arpaṇe māḍuvudu, pradakṣiṇaṁ samarpayāmi eṁdu.",
      "devanagari": "ಬರಲಿಕ್ಕೆ ಅವಕಾಶವಿದ್ದಲ್ಲಿ ಪ್ರದಕ್ಷಿಣೆ ಬರಲಿಕ್ಕೂ ಉಂಟು ಸಪ್ತಾಸ್ಯಾಸನ್ ಪರಿಧಯಹ ತ್ರಿಸಪ್ತ ಸಮಿದ ಕೃತಾಹ ದೇವಾಯಜ್ಞಂ ತನ್ವಾನ ಅಪ್ನಂನ್ ಪುರುಷಂ ಪಶುಂ ಎಂದು ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಪ್ರದಕ್ಷಿಣಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು ಶಂಖದಲ್ಲಿ ಒಂದು ದೇವರಿಗೆ ತೋರಿಸಿ ಅರ್ಘ್ಯ ಪಾತ್ರೆಯಲ್ಲಿ ನೀರನ್ನು ಅರ್ಪಣೆ ಮಾಡುವುದು ಪ್ರದಕ್ಷಿಣಂ ಸಮರ್ಪಯಾಮಿ",
      "meaning": "Complete source-audio coverage for pradakṣiṇā.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ಪ್ರದಕ್ಷಿಣೆ ಬರಲಿಕ್ಕೆ ಅವಕಾಶವಿದ್ದಲ್ಲಿ ಪ್ರದಕ್ಷಿಣೆ ಬರಲಿಕ್ಕೂ ಉಂಟು. ಸಪ್ತಾಸ್ಯಾಸನ್ ಪರಿಧಯಃ, ತ್ರಿಃ ಸಪ್ತ ಸಮಿಧಃ ಕೃತಾಃ. ದೇವಾ ಯದ್ಯಜ್ಞಂ ತನ್ವಾನಾ ಅಬಧ್ನನ್ ಪುರುಷಂ ಪಶುಂ ಎಂದು. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಓಂ ಶ್ರೀಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ, ಪ್ರದಕ್ಷಿಣಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು ಶಂಖದಲ್ಲಿ ಒಂದು ದೇವರಿಗೆ ತೋರಿಸಿ ಅರ್ಘ್ಯಪಾತ್ರೆಯಲ್ಲಿ ನೀರನ್ನು ಅರ್ಪಣೆ ಮಾಡುವುದು, ಪ್ರದಕ್ಷಿಣಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು. ",
      "captionOriginal": "ಬರಲಿಕ್ಕೆ ಅವಕಾಶವಿದ್ದಲ್ಲಿ ಪ್ರದಕ್ಷಿಣೆ ಬರಲಿಕ್ಕೂ ಉಂಟು ಸಪ್ತಾಸ್ಯಾಸನ್ ಪರಿಧಯಹ ತ್ರಿಸಪ್ತ ಸಮಿದ ಕೃತಾಹ ದೇವಾಯಜ್ಞಂ ತನ್ವಾನ ಅಪ್ನಂನ್ ಪುರುಷಂ ಪಶುಂ ಎಂದು ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಪ್ರದಕ್ಷಿಣಂ ಸಮರ್ಪಯಾಮಿ ಎಂದು ಶಂಖದಲ್ಲಿ ಒಂದು ದೇವರಿಗೆ ತೋರಿಸಿ ಅರ್ಘ್ಯ ಪಾತ್ರೆಯಲ್ಲಿ ನೀರನ್ನು ಅರ್ಪಣೆ ಮಾಡುವುದು ಪ್ರದಕ್ಷಿಣಂ ಸಮರ್ಪಯಾಮಿ",
      "losslessRoman": "pradakṣiṇe baralikke avakāśaviddalli pradakṣiṇe baralikkū uṁṭu. saptāsyāsan paridhayaḥ, triḥ sapta samidhaḥ kr̥tāḥ. dēvā yadyajñaṁ tanvānā abadhnan puruṣaṁ paśuṁ eṁdu. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmī nārāyaṇāya, pradakṣiṇaṁ samarpayāmi eṁdu śaṁkhadalli oṁdu dēvarige tōrisi arghyapātreyalli nīrannu arpaṇe māḍuvudu, pradakṣiṇaṁ samarpayāmi eṁdu.",
