      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "naṁtara yajñēna yajñamayajaṁta dēvāḥ, tāni dharmāṇi prathamānyāsan, tē ha nākaṁ mahimānaḥ sacaṁta, yatra pūrvē sādhyāḥ saṁti dēvāḥ. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmī nārāyaṇāya, suvarṇa dakṣiṇāṁ samarpayāmi. śaṁkhadalli nīrannu dēvarige tōrisi samarpaṇe māḍuvudu. iṣṭu hadināru pūje.",
      "devanagari": "ಎಂದು ನಂತರ ಯಜ್ಞೇನ ಯಜ್ಞಮಯಜಂತ ದೇವಾಹ ತಾನಿ ಪ್ರಥಮಾನ್ಯಾಸನ್ ತೇಹನಾಕಂ ಮಹಿಮಾನ ಸಚಂತ ಯತ್ರ ಪೂರ್ವೇ ಸಾಧ್ಯಸಂತಿ ದೇವಾಹ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಶ್ರೀ ಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ ಸುವರ್ಣ ದಕ್ಷಿಣಾಂ ಸಮರ್ಪಯಾಮಿ ಶಂಖದಲ್ಲಿ ನೀರನ್ನು ದೇವರಿಗೆ ತೋರಿಸಿ ಸಮರ್ಪಣೆ ಮಾಡುವುದು ಇಷ್ಟು 16 ಪೂಜೆ ಇದಲ್ಲದೆ ಬೇರೆ ಅನುಪಚಾರ ಪೂಜೆಯು ಅಂತ ಇದೆ",
