      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ನಂತರ ಯಜ್ಞೇನ ಯಜ್ಞಮಯಜಂತ ದೇವಾಃ, ತಾನಿ ಧರ್ಮಾಣಿ ಪ್ರಥಮಾನ್ಯಾಸನ್, ತೇ ಹ ನಾಕಂ ಮಹಿಮಾನಃ ಸಚಂತ, ಯತ್ರ ಪೂರ್ವೇ ಸಾಧ್ಯಾಃ ಸಂತಿ ದೇವಾಃ. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಓಂ ಶ್ರೀಲಕ್ಷ್ಮೀ ನಾರಾಯಣಾಯ, ಸುವರ್ಣ ದಕ್ಷಿಣಾಂ ಸಮರ್ಪಯಾಮಿ. ಶಂಖದಲ್ಲಿ ನೀರನ್ನು ದೇವರಿಗೆ ತೋರಿಸಿ ಸಮರ್ಪಣೆ ಮಾಡುವುದು. ಇಷ್ಟು ಹದಿನಾರು ಪೂಜೆ. ",
