      "losslessRoman": "naṁtara yajñēna yajñamayajaṁta dēvāḥ, tāni dharmāṇi prathamānyāsan, tē ha nākaṁ mahimānaḥ sacaṁta, yatra pūrvē sādhyāḥ saṁti dēvāḥ. ōṁ ōṁ namō nārāyaṇāya, ōṁ śrīlakṣmī nārāyaṇāya, suvarṇa dakṣiṇāṁ samarpayāmi. śaṁkhadalli nīrannu dēvarige tōrisi samarpaṇe māḍuvudu. iṣṭu hadināru pūje.",
