      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "idallade bēre anupacāra pūjeyū uṁṭide. nīvu śaṁkhadalli nīrannu tuṁbikoṁḍu elladakkū kūḍa nīrannē upayōgisuvudu dēvara pūje. sr̥ṣṭi āraṁbhadalli modalu dēvaru nīrannē sr̥ṣṭi māḍittu āddariṁdāgi ella pūjeyū illadiddalli upacārada badalāgi nīrannē arpaṇe māḍuvudu. chatraṁ samarpayāmi, cāmaraṁ samarpayāmi, vyajanaṁ samarpayāmi, pādukē samarpayāmi, gītaṁ, nr̥tyaṁ, vāditrāṇi, samasta rājōpacāra pūjāḥ samarpayāmi.",
      "devanagari": "ಶಂಖದಲ್ಲಿ ನೀರನ್ನು ತುಂಬಿಕೊಂಡು ಎಲ್ಲದಕ್ಕೂ ಕೂಡ ನೀರನ್ನೇ ಉಪಯೋಗಿಸುವುದು ದೇವರ ಪೂಜೆಗೆ ಸೃಷ್ಟಿಯ ಆರಂಭದಲ್ಲಿ ಮೊದಲು ದೇವರು ನೀರನ್ನೇ ಸೃಷ್ಟಿ ಮಾಡಿದ್ದು ಆದ್ದರಿಂದಾಗಿ ಎಲ್ಲ ಪೂಜೆಯು ಇಲ್ಲದಿದ್ದಲ್ಲಿ ಆ ಉಪಚಾರದ ಬದಲಾಗಿ ನೀರನ್ನೇ ಅರ್ಪಣೆ ಮಾಡುವುದು ಛತ್ರಂ ಸಮರ್ಪಯಾಮಿ ಚಾಮರಂ ಸಮರ್ಪಯಾಮಿ ವ್ಯಜನಂ ಗೀತಂ ನೃತ್ಯ ವಾದಿತ್ರಾಣಿ ಸಮಸ್ತ ರಾಜೋಪಚಾರ ಪೂಜಾಹ",
      "meaning": "Complete source-audio coverage for other rājōpacāras.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ಇದಲ್ಲದೆ ಬೇರೆ ಅನುಪಚಾರ ಪೂಜೆಯೂ ಉಂಟಿದೆ. ನೀವು ಶಂಖದಲ್ಲಿ ನೀರನ್ನು ತುಂಬಿಕೊಂಡು ಎಲ್ಲದಕ್ಕೂ ಕೂಡ ನೀರನ್ನೇ ಉಪಯೋಗಿಸುವುದು ದೇವರ ಪೂಜೆ. ಸೃಷ್ಟಿ ಆರಂಭದಲ್ಲಿ ಮೊದಲು ದೇವರು ನೀರನ್ನೇ ಸೃಷ್ಟಿ ಮಾಡಿತ್ತು ಆದ್ದರಿಂದಾಗಿ ಎಲ್ಲ ಪೂಜೆಯೂ ಇಲ್ಲದಿದ್ದಲ್ಲಿ ಉಪಚಾರದ ಬದಲಾಗಿ ನೀರನ್ನೇ ಅರ್ಪಣೆ ಮಾಡುವುದು. ಛತ್ರಂ ಸಮರ್ಪಯಾಮಿ, ಚಾಮರಂ ಸಮರ್ಪಯಾಮಿ, ವ್ಯಜನಂ ಸಮರ್ಪಯಾಮಿ, ಪಾದುಕೇ ಸಮರ್ಪಯಾಮಿ, ಗೀತಂ, ನೃತ್ಯಂ, ವಾದಿತ್ರಾಣಿ, ಸಮಸ್ತ ರಾಜೋಪಚಾರ ಪೂಜಾಃ ಸಮರ್ಪಯಾಮಿ. ",
      "captionOriginal": "ಶಂಖದಲ್ಲಿ ನೀರನ್ನು ತುಂಬಿಕೊಂಡು ಎಲ್ಲದಕ್ಕೂ ಕೂಡ ನೀರನ್ನೇ ಉಪಯೋಗಿಸುವುದು ದೇವರ ಪೂಜೆಗೆ ಸೃಷ್ಟಿಯ ಆರಂಭದಲ್ಲಿ ಮೊದಲು ದೇವರು ನೀರನ್ನೇ ಸೃಷ್ಟಿ ಮಾಡಿದ್ದು ಆದ್ದರಿಂದಾಗಿ ಎಲ್ಲ ಪೂಜೆಯು ಇಲ್ಲದಿದ್ದಲ್ಲಿ ಆ ಉಪಚಾರದ ಬದಲಾಗಿ ನೀರನ್ನೇ ಅರ್ಪಣೆ ಮಾಡುವುದು ಛತ್ರಂ ಸಮರ್ಪಯಾಮಿ ಚಾಮರಂ ಸಮರ್ಪಯಾಮಿ ವ್ಯಜನಂ ಗೀತಂ ನೃತ್ಯ ವಾದಿತ್ರಾಣಿ ಸಮಸ್ತ ರಾಜೋಪಚಾರ ಪೂಜಾಹ",
      "losslessRoman": "idallade bēre anupacāra pūjeyū uṁṭide. nīvu śaṁkhadalli nīrannu tuṁbikoṁḍu elladakkū kūḍa nīrannē upayōgisuvudu dēvara pūje. sr̥ṣṭi āraṁbhadalli modalu dēvaru nīrannē sr̥ṣṭi māḍittu āddariṁdāgi ella pūjeyū illadiddalli upacārada badalāgi nīrannē arpaṇe māḍuvudu. chatraṁ samarpayāmi, cāmaraṁ samarpayāmi, vyajanaṁ samarpayāmi, pādukē samarpayāmi, gītaṁ, nr̥tyaṁ, vāditrāṇi, samasta rājōpacāra pūjāḥ samarpayāmi.",
