      "sanskrit": "Lossless GPT transcription reconciled against YouTube's timed Kannada captions",
      "mantra": "āmēle. śaṁkhadiṁda śaṁkhadalli nīrannu tuṁbikoṁḍu bhramaṇa māḍuvudu, mūru bāri. imā āpaḥ śivāḥ saṁtu. ōṁ ōṁ namō nārāyaṇāya, ōṁ ōṁ namō nārāyaṇāya, ōṁ ōṁ namō nārāyaṇāya, ōṁ. ī rīti śaṁkhadalliruva nīrannu pratyēka pātrege hākikoḷḷuvudu.",
      "devanagari": "ಸಮರ್ಪಯಾಮಿ ಎಂದು ಆಮೇಲೆ ಭ್ರಮಣ ಮಾಡುವುದು ಮೂರು ಬಾರಿ ಇಮಾ ಆಪಶಿ ಸಂತು ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ ಓಂ ಈ ರೀತಿ ಶಂಖದಲ್ಲಿರುವ ನೀರನ್ನು ಪ್ರತ್ಯೇಕ ಪಾತ್ರೆಗೆ ದೇವರನ್ನು ವಿಸರ್ಜನೆ ಮಾಡುವುದು",
      "meaning": "Complete source-audio coverage for concluding śaṅkha-bhramaṇa.",
      "action": "Follow the interleaved Sanskrit recitation and English action boxes below.",
      "originalScript": "ಆಮೇಲೆ. ಶಂಖದಿಂದ ಶಂಖದಲ್ಲಿ ನೀರನ್ನು ತುಂಬಿಕೊಂಡು ಭ್ರಮಣ ಮಾಡುವುದು, ಮೂರು ಬಾರಿ. ಇಮಾ ಆಪಃ ಶಿವಾಃ ಸಂತು. ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಓಂ ಓಂ ನಮೋ ನಾರಾಯಣಾಯ, ಓಂ. ಈ ರೀತಿ ಶಂಖದಲ್ಲಿರುವ ನೀರನ್ನು ಪ್ರತ್ಯೇಕ ಪಾತ್ರೆಗೆ ಹಾಕಿಕೊಳ್ಳುವುದು. ",
