      "originalScript": "ಆಮೇಲೆ ಕೃಷ್ಣಾರ್ಪಣ. ... ತಪಃ ಪೂಜಾ ಕ್ರಿಯಾ ದಿಶು, ನ್ಯೂನಂ ಸಂಪೂರ್ಣತಾಂ ಯಾತಿ ಸದ್ಯೋ ವಂದೇ ತಮಚ್ಯುತಂ. ಮಂತ್ರಹೀನಂ ಕ್ರಿಯಾಹೀನಂ ಭಕ್ತಿಹೀನಂ ರಮಾಪತೇ, ಯತ್ ಕೃತಂ ತು ಮಯಾ ದೇವ ಪರಿಪೂರ್ಣಂ ತದಸ್ತು ಮೇ. ಅನೇನ ಭಗವತಃ ಶ್ರೀಲಕ್ಷ್ಮೀನಾರಾಯಣಸ್ಯ ಪೂಜಾ ಕರ್ಮಣಾ, ಮಧ್ವಾಂತರ್ಗತಃ ಗೋಪಾಲಕೃಷ್ಣಃ ಪ್ರೀಯತಾಂ, ಪ್ರೀತಃ ವರದೋ ಭವತು ಶ್ರೀಕೃಷ್ಣಾರ್ಪಣಮಸ್ತು. ನಂತರ ಏನಾದರೂ ಲೋಪವಾಗಿದ್ದಲ್ಲಿ ಪರಿಹಾರವಾಗಲಿ ಅಂತ ನಾಮತ್ರಯ ಜಪ ಮಾಡುವುದು. ಮಧ್ಯೆ ಮಂತ್ರ ತಂತ್ರ ಸ್ವರ ವರ್ಣ ನ್ಯೂನಾತಿರಿಕ್ತ ಲೋಪದೋಷ ಪ್ರಾಯಶ್ಚಿತ್ತಾರ್ಥಂ ನಾಮತ್ರಯ ಮಂತ್ರ ಜಪಂ ಕರಿಷ್ಯೇ. ಓಂ ಅಚ್ಯುತಾಯ ನಮಃ, ಓಂ ಅನಂತಾಯ ನಮಃ, ಓಂ ಗೋವಿಂದಾಯ ನಮಃ, ಓಂ ಅಚ್ಯುತಾಯ ನಮಃ, ಓಂ ಅನಂತಾಯ ನಮಃ, ಓಂ ಗೋವಿಂದಾಯ ನಮಃ, ಓಂ ಅಚ್ಯುತಾಯ ನಮಃ, ಓಂ ಅನಂತಾಯ ನಮಃ, ಓಂ ಗೋವಿಂದಾಯ ನಮಃ, ಕಾಯೇನ ವಾಚಾ ಮನಸೇಂದ್ರಿಯೈರ್ವಾ ಹೃದ್ಯಾತ್ಮನಾ ವಾ ನುಸೃತ ಸ್ವಭಾವಾತ್, ಕರೋಮಿ ಯದ್ಯತ್ ಸಕಲಂ ಪರಸ್ಮೈ ನಾರಾಯಣಾಯೇತಿ ಸಮರ್ಪಯಾಮಿ. ",
      "captionOriginal": "ನಾಮೋಕ್ತ್ಯ ತಪಃ ಪೂಜಾ ಕ್ರಿಯಾದಿಶು ನ್ಯೂನಂ ಸಂಪೂರ್ಣತಾಮ್ಯಾತಿ ಸದ್ಯೋ ವಂದೇ ತಮಚ್ಚುತಂ ಮಂತ್ರಹೀನಂ ಕ್ರಿಯಾಹೀನಂ ಭಕ್ತಿಹೀನಂ ರಮಾಪತೆ ಯತ್ಕೃತಂತುಮಯ ದೇವ ಪರಿಪೂರ್ಣಂ ತದಸ್ತುಮೇ ಅನೇನ ಭಗವತಃ ಶ್ರೀ ಲಕ್ಷ್ಮೀನಾರಾಯಣಸ್ಯ ಪೂಜಾ ಕ್ರಮಣ ಮಧ್ವಾಂತರ್ಗತಃ ಗೋಪಾಲಕೃಷ್ಣ ಪ್ರಿಯತಾಂ ಪ್ರೀತಃ ವರದೋ ಭವತು ಶ್ರೀಕೃಷ್ಣಾರ್ಪಣಮಸ್ತು ನಂತರ ಏನಾದರೂ ಲೋಪವಾಗಿದ್ದಲ್ಲಿ ಪರಿಹಾರವಾಗಲಿ ಅಂತ ನಾಮತ್ರಯ ಜಪ ಮಾಡುವುದು ಮಧ್ಯೆ ಮಂತ್ರ ತಂತ್ರ ಸ್ವರ ವರ್ಣ ನ್ಯೂನ ಅತಿರಿಕ್ತ ಲೋಪದೋಷ ಪ್ರಾಯಶ್ಚಿತ್ತಾರ್ಥಂ ನಾಮತ್ರಯ ಮಂತ್ರ ಜಪಂ ಕರಿಶ್ಯೆ ಓಂ ಅಚ್ಯುತಾಯ ನಮಃ ಓಂ ಅನಂತಾಯ ನಮಃ ಓಂ ಗೋವಿಂದಾಯ ನಮಃ ಓಂ ಅಚ್ಯುತಾಯ ನಮಃ ಓಂ ಅನಂತಾಯ ನಮಃ ಓಂ ಓಂ ಗೋವಿಂದಾಯ ನಮಃ ಓಂ ಅಚ್ಯುತಾಯ ನಮಃ ಓಂ ಅನಂತಾಯ ನಮಃ ಓಂ ಗೋವಿಂದಾಯ ನಮಃ ಕಾಯೇನ ವಾಚ ಮನಸಾ ಹೃದ್ಯಾತ್ಮನಾವನು ಸ್ವಭಾವಹ ಕರೋಮಿ ಯದ್ಯತ್ ಸಕಲಂ ಪರಸ್ಮೈ ನಾರಾಯಣಾಯೇತಿ",
      "losslessRoman": "āmēle kr̥ṣṇārpaṇa. ... tapaḥ pūjā kriyā diśu, nyūnaṁ saṁpūrṇatāṁ yāti sadyō vaṁdē tamacyutaṁ. maṁtrahīnaṁ kriyāhīnaṁ bhaktihīnaṁ ramāpatē, yat kr̥taṁ tu mayā dēva paripūrṇaṁ tadastu mē. anēna bhagavataḥ śrīlakṣmīnārāyaṇasya pūjā karmaṇā, madhvāṁtargataḥ gōpālakr̥ṣṇaḥ prīyatāṁ, prītaḥ varadō bhavatu śrīkr̥ṣṇārpaṇamastu. naṁtara ēnādarū lōpavāgiddalli parihāravāgali aṁta nāmatraya japa māḍuvudu. madhye maṁtra taṁtra svara varṇa nyūnātirikta lōpadōṣa prāyaścittārthaṁ nāmatraya maṁtra japaṁ kariṣyē. ōṁ acyutāya namaḥ, ōṁ anaṁtāya namaḥ, ōṁ gōviṁdāya namaḥ, ōṁ acyutāya namaḥ, ōṁ anaṁtāya namaḥ, ōṁ gōviṁdāya namaḥ, ōṁ acyutāya namaḥ, ōṁ anaṁtāya namaḥ, ōṁ gōviṁdāya namaḥ, kāyēna vācā manasēṁdriyairvā hr̥dyātmanā vā nusr̥ta svabhāvāt, karōmi yadyat sakalaṁ parasmai nārāyaṇāyēti samarpayāmi.",
