          "sourceOriginal": "ಆದರೆ ನಾವು ಬೇರೆ ಕಡೆ ಹೋಗದಾಗ ಅವಾಗ ದೇವರನ್ನು ನಾವು ಕಟ್ಟಿಡಬೇಕಾಗುತ್ತೆ. ",
          "sourceRoman": "ādare nāvu bēre kaḍe hōgadāga avāga dēvarannu nāvu kaṭṭiḍabēkāgutte.",
          "english": "But when we don't go somewhere else, then we have to bind God."
