          "sourceRoman": "tīrthavanna prāśana māḍabēkādre nāvu dēvara pūje koneyalli śaṁkhavannu bhramaṇa māḍidvi, alvā?",
          "english": "If we have to pray to the tirtha, we should have turned the conch at the end of the worship of God, right?"
