          "sourceOriginal": "ಇಲ್ಲಾಂದ್ರೆ ದೇವರು ಕೊಟ್ಟದ್ದನ್ನ ದೇವರಿಗೆ ಅರ್ಪಣೆ ಮಾಡದೆ ಹೋದ್ರೆ ನಾವು ಕಳ್ಳರಾಗ್ತೀವಿ. ",
          "sourceRoman": "illāṁdre dēvaru koṭṭaddanna dēvarige arpaṇe māḍade hōdre nāvu kaḷḷarāgtīvi.",
